  var g = new Function(m[1] + "\nreturn { isInteractiveBlockType: isInteractiveBlockType, paletteAllowsType: paletteAllowsType, INTERACTIVE_BLOCK_TYPES: INTERACTIVE_BLOCK_TYPES };")();
