// ---- Product Rail #1: ProductsStore adapter round-trip (real read/write, not just wiring) --
section("product-rail ProductsStore");
(function () {
  var ed = src("src/editor.js");
  var pureFence = ed.match(/\/\* @pure-start \*\/([\s\S]*?)\/\* @pure-end \*\//);
  if (!pureFence) { ok("locate @pure fence", false); return; }
  var adapterFence = ed.match(/\/\* @products-adapter-start \*\/([\s\S]*?)\/\* @products-adapter-end \*\//);
  if (!adapterFence) { ok("locate @products-adapter fence", false); return; }
  var fake = {}; // a minimal Storage-like stub, isolated per test run
  var fakeLocalStorage = {
    getItem: function (k) { return Object.prototype.hasOwnProperty.call(fake, k) ? fake[k] : null; },
    setItem: function (k, v) { fake[k] = v; }
  };
  // Extracted from the REAL source (not re-typed), so this can't silently drift from
  // what actually ships: the durable-write core (writeStore) + the real adapter object.
  var g = new Function("localStorage",
    pureFence[1] + adapterFence[1] +
    "\nreturn { browserProductsAdapter: browserProductsAdapter };"
  )(fakeLocalStorage);
  ok("readProducts is null before any write (no stray default)", g.browserProductsAdapter.readProducts() === null);
  var payload = JSON.stringify({ "prod-a": { id: "prod-a", name: "Radar", createdAt: 1000 } });
  var wr = g.browserProductsAdapter.writeProducts(payload);
  ok("writeProducts reports ok", wr.ok === true);
  ok("readProducts round-trips the exact JSON just written", g.browserProductsAdapter.readProducts() === payload);
  ok("round-tripped JSON parses back to the same shape", JSON.parse(g.browserProductsAdapter.readProducts())["prod-a"].name === "Radar");
})();

// ---- #67: .verso portable package (zip codec + round-trip) ----------------
section("#67 .verso format");
(function () {
  var t = src("src/verso-format.js");
  var win = {};
  new Function("window", t)(win);
  var VF = win.VersoFormat;
  if (!VF || !VF.buildPackage || !VF.readPackage) { ok("VersoFormat loaded", false); return; }
  ok("VersoFormat loaded", true);

  var b64Url = "data:image/png;base64," + Buffer.from([1, 2, 3, 4, 250, 251, 252, 253]).toString("base64");
  var rawUrl = "data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg'><rect/></svg>";
  var doc = { meta: { code: "C-1", title: "Fire Safety" }, pages: [{ blocks: [{ type: "image", src: "asset:aaa" }, { type: "image", src: "asset:bbb" }] }] };
  var assets = { aaa: { dataUrl: b64Url, mime: "image/png" }, bbb: { dataUrl: rawUrl, mime: "image/svg+xml" } };

  var pkg = VF.buildPackage(doc, assets, {});
  ok("buildPackage -> non-empty bytes", pkg instanceof Uint8Array && pkg.length > 0);

  var back = VF.readPackage(pkg);
  ok("manifest formatVersion", back.manifest.formatVersion === VF.FORMAT_VERSION);
  ok("manifest code+title", back.manifest.code === "C-1" && back.manifest.title === "Fire Safety");
  ok("doc round-trips deep-equal", JSON.stringify(back.doc) === JSON.stringify(doc));
  // CRITICAL: dataURLs must round-trip byte-identical, else content-hash ids drift + refs break.
  ok("base64 asset dataURL identical (stable id)", back.assets.aaa.dataUrl === b64Url);
  ok("raw (svg) asset dataURL identical (stable id)", back.assets.bbb.dataUrl === rawUrl);
  ok("asset mimes preserved", back.assets.aaa.mime === "image/png" && back.assets.bbb.mime === "image/svg+xml");

  // The package must be a STANDARD-COMPLIANT zip (external tools can open it).
  var os = require("os");
  var tmp = path.join(os.tmpdir(), "verso-fmt-test-" + process.pid + ".verso");
  fs.writeFileSync(tmp, Buffer.from(pkg));
  var uz = cp.spawnSync("unzip", ["-t", tmp], { encoding: "utf8" });
  ok("system `unzip -t` validates the package", uz.status === 0);
  try { fs.unlinkSync(tmp); } catch (e) {}

  var threw = false; try { VF.readPackage(new Uint8Array([1, 2, 3])); } catch (e) { threw = true; }
  ok("non-zip input rejected", threw);
})();

// ---- #69: clobber-proof migration core (browser -> file cutover) ----------
section("#69 migration cutover");
(function () {
  var t = src("src/migration.js");
  var win = {};
  new Function("window", t)(win);
  var M = win.Migration;
  if (!M || !M.run || !M.verifyRegistries) { ok("Migration loaded", false); return; }
  ok("Migration loaded", true);

  // verifyRegistries (pure read-back gate) --------------------------------
  var reg3 = JSON.stringify({ "C-1": { meta: { code: "C-1" } }, "C-2": { meta: { code: "C-2" } }, "C-3": { meta: { code: "C-3" } } });
  ok("verify identical -> ok", M.verifyRegistries(reg3, reg3).ok === true);
  ok("verify empty read-back -> fail", M.verifyRegistries(reg3, null).ok === false);
  ok("verify count mismatch -> fail", M.verifyRegistries(reg3, JSON.stringify({ "C-1": {}, "C-2": {} })).ok === false);
  ok("verify code mismatch -> fail", M.verifyRegistries(reg3, JSON.stringify({ "C-1": {}, "C-2": {}, "C-9": {} })).ok === false);
  ok("verify missing doc -> fail", M.verifyRegistries(reg3, JSON.stringify({ "C-1": {}, "C-2": {}, "C-3": null })).ok === false);
  ok("verify unparseable read-back -> fail", M.verifyRegistries(reg3, "{not json").ok === false);

  // verifyLibrary (#18: same read-back gate, for the shared component library) --------
  var lib2 = JSON.stringify({ components: { "comp-1": { name: "A" }, "comp-2": { name: "B" } } });
  ok("verifyLibrary loaded", typeof M.verifyLibrary === "function");
  ok("verifyLibrary identical -> ok", M.verifyLibrary(lib2, lib2).ok === true && M.verifyLibrary(lib2, lib2).count === 2);
  ok("verifyLibrary empty read-back -> fail", M.verifyLibrary(lib2, null).ok === false);
  ok("verifyLibrary key count mismatch -> fail", M.verifyLibrary(lib2, JSON.stringify({ components: { "comp-1": {} } })).ok === false);
  ok("verifyLibrary key mismatch -> fail", M.verifyLibrary(lib2, JSON.stringify({ components: { "comp-1": {}, "comp-9": {} } })).ok === false);
  ok("verifyLibrary unparseable read-back -> fail", M.verifyLibrary(lib2, "{not json").ok === false);
  ok("verifyLibrary missing components key treated as empty -> matches empty", M.verifyLibrary(JSON.stringify({}), JSON.stringify({})).ok === true);

  // Fakes: a browser source + a file store, with injectable failure hooks.
  function fakeBrowser(json) { return { readRegistry: function () { return json; } }; }
  function fakeFile(opts) {
    opts = opts || {};
    var stored = null, writes = 0;
    return {
      writeRegistry: function (json) { writes++; if (opts.failWrite) return { ok: false, error: "disk full" }; stored = json; return { ok: true }; },
      readRegistry: function () { return opts.corruptRead ? JSON.stringify({ "C-1": {} }) : stored; },
      _writes: function () { return writes; },
      _stored: function () { return stored; }
    };
  }
  // Independent suppression spy (don't rely on the module global across cases).
  function spySuppress() {
    var s = { on: false, suppressed: 0, resumed: 0 };
    return { s: s, suppress: function () { s.on = true; s.suppressed++; }, resume: function () { s.on = false; s.resumed++; } };
  }
  function goodBackup(reg) { return { ok: true, count: Object.keys(reg).length }; }

  // HAPPY PATH: read -> backup -> suppress -> write -> verify -> flip.
  (function () {
    var file = fakeFile(); var sp = spySuppress();
    var r = M.run(fakeBrowser(reg3), file, { backup: goodBackup, suppress: sp.suppress, resume: sp.resume });
    ok("happy: ok+flip", r.ok === true && r.flip === true);
    ok("happy: all 3 codes returned", r.codes.length === 3);
    ok("happy: target written with source json", file._stored() === reg3);
    ok("happy: saves SUPPRESSED and NOT resumed (stay off through reload)", sp.s.on === true && sp.s.resumed === 0);
  })();

  // BACKUP GATE: a failed backup aborts BEFORE any target write or suppression.
  (function () {
    var file = fakeFile(); var sp = spySuppress();
    var r = M.run(fakeBrowser(reg3), file, { backup: function () { return { ok: false, error: "backup dir unwritable" }; }, suppress: sp.suppress, resume: sp.resume });
    ok("backup fail: not ok, no flip", r.ok === false && r.flip === false && r.stage === "backup");
    ok("backup fail: target NEVER written", file._writes() === 0);
    ok("backup fail: saves never suppressed (browser stays live)", sp.s.on === false && sp.s.suppressed === 0);
  })();
  (function () {
    var file = fakeFile(); var sp = spySuppress();
    var r = M.run(fakeBrowser(reg3), file, { backup: function (reg) { return { ok: true, count: 1 }; }, suppress: sp.suppress, resume: sp.resume });
    ok("incomplete backup (1/3): abort, no write", r.ok === false && r.stage === "backup" && file._writes() === 0);
  })();

  // WRITE FAILURE: file store write fails -> abort, saves RESUMED (browser authoritative).
  (function () {
    var file = fakeFile({ failWrite: true }); var sp = spySuppress();
    var r = M.run(fakeBrowser(reg3), file, { backup: goodBackup, suppress: sp.suppress, resume: sp.resume });
    ok("write fail: not ok, no flip, stage=write", r.ok === false && r.flip === false && r.stage === "write");
    ok("write fail: saves RESUMED (rollback to browser)", sp.s.on === false && sp.s.resumed === 1);
  })();

  // VERIFY FAILURE: read-back drifts -> abort, saves RESUMED, no flip.
  (function () {
    var file = fakeFile({ corruptRead: true }); var sp = spySuppress();
    var r = M.run(fakeBrowser(reg3), file, { backup: goodBackup, suppress: sp.suppress, resume: sp.resume });
    ok("verify fail: not ok, no flip, stage=verify", r.ok === false && r.flip === false && r.stage === "verify");
    ok("verify fail: saves RESUMED (browser stays authoritative)", sp.s.on === false && sp.s.resumed === 1);
  })();

  // EMPTY SOURCE: nothing to migrate -> abort before backup/suppress.
  (function () {
    var file = fakeFile(); var sp = spySuppress();
    var r = M.run(fakeBrowser(null), file, { backup: goodBackup, suppress: sp.suppress, resume: sp.resume });
    ok("empty source: abort at read, nothing touched", r.ok === false && r.stage === "read" && file._writes() === 0 && sp.s.suppressed === 0);
  })();

  // IDEMPOTENT: a re-run into an already-migrated file store is a safe no-op-equivalent.
  (function () {
    var file = fakeFile(); var sp = spySuppress();
    M.run(fakeBrowser(reg3), file, { backup: goodBackup, suppress: sp.suppress, resume: sp.resume });
    var first = file._stored();
    var r2 = M.run(fakeBrowser(reg3), file, { backup: goodBackup, suppress: sp.suppress, resume: sp.resume });
    ok("re-run: still ok, store byte-identical", r2.ok === true && file._stored() === first);
  })();

  // DEFAULT GUARD: run() with no suppress/resume hooks toggles the real module guard;
  // on success it stays suppressed (fresh boot resets it).
  (function () {
    M.resume();
    ok("guard starts off", M.savesSuppressed() === false);
    M.run(fakeBrowser(reg3), fakeFile(), { backup: goodBackup });
    ok("guard on after successful run (until reload)", M.savesSuppressed() === true);
    M.resume();
  })();

  // ---- makeBackupFn: the HARD backup gate (pure, dep-injected) -----------
  (function () {
    // Fake VersoFormat: builds a non-empty package unless told to throw.
    var fakeVF = { buildPackage: function (d, a, m) { if (d && d.__boom) throw new Error("pack boom"); return new Uint8Array([1, 2, 3, 4]); } };
    function reg(n) { var r = {}; for (var i = 1; i <= n; i++) r["C-" + i] = { meta: { code: "C-" + i } }; return r; }
    function sink(opts) {
      opts = opts || {}; var files = {};
      return {
        files: files,
        writeFile: function (path, bytes) { if (opts.failAt && path.indexOf(opts.failAt) !== -1) return { ok: false, error: "disk full" }; files[path] = bytes; return { ok: true }; },
        verifySize: function (path) { return opts.corruptAt && path.indexOf(opts.corruptAt) !== -1 ? 0 : (files[path] ? files[path].length : 0); }
      };
    }
    // Happy path: 3 courses -> 3 verified .verso backups.
    var s = sink();
    var bf = M.makeBackupFn({ versoFormat: fakeVF, writeFile: s.writeFile, verifySize: s.verifySize, tsLabel: "T", collectAssets: function () { return {}; } });
    var r = bf(reg(3));
    ok("backup happy: ok + count 3", r.ok === true && r.count === 3);
    ok("backup happy: dir is pre-cutover-<ts>", r.dir === "backups/pre-cutover-T/");
    ok("backup happy: one .verso per course", Object.keys(s.files).length === 3 && !!s.files["backups/pre-cutover-T/C-2.verso"]);
    // Write failure mid-way -> abort with partial count, browser untouched (caller aborts).
    var s2 = sink({ failAt: "C-2" });
    var r2 = M.makeBackupFn({ versoFormat: fakeVF, writeFile: s2.writeFile, verifySize: s2.verifySize, tsLabel: "T" })(reg(3));
    ok("backup write fail: not ok, count 1", r2.ok === false && r2.count === 1);
    // Verify failure (0 bytes on disk) -> not ok (the 'verified written' gate).
    var s3 = sink({ corruptAt: "C-1" });
    var r3 = M.makeBackupFn({ versoFormat: fakeVF, writeFile: s3.writeFile, verifySize: s3.verifySize, tsLabel: "T" })(reg(2));
    ok("backup verify fail (0 bytes): not ok", r3.ok === false);
    // buildPackage throws -> not ok.
    var s4 = sink();
    var r4 = M.makeBackupFn({ versoFormat: fakeVF, writeFile: s4.writeFile, verifySize: s4.verifySize, tsLabel: "T" })({ "C-1": { __boom: true } });
    ok("backup build throw: not ok", r4.ok === false);
    // No sink / no VersoFormat -> not ok (never silently 'succeeds').
    ok("backup no sink: not ok", M.makeBackupFn({ versoFormat: fakeVF, tsLabel: "T" })(reg(1)).ok === false);
    ok("backup no VersoFormat: not ok", M.makeBackupFn({ writeFile: sink().writeFile, tsLabel: "T" })(reg(1)).ok === false);
    // End-to-end: makeBackupFn result feeds run()'s gate (count must match course count).
    var s5 = sink(); var sp = spySuppress();
    var rr = M.run(fakeBrowser(reg3), fakeFile(), {
      backup: M.makeBackupFn({ versoFormat: fakeVF, writeFile: s5.writeFile, verifySize: s5.verifySize, tsLabel: "T" }),
      suppress: sp.suppress, resume: sp.resume
    });
    ok("run + real makeBackupFn: ok + flip", rr.ok === true && rr.flip === true && Object.keys(s5.files).length === 3);

    // ASYNC backup gate (live path): awaits Promise-returning sinks.
    __async.push((async function () {
      var files = {};
      var okDeps = { versoFormat: fakeVF, tsLabel: "T",
        writeFile: function (p, b) { return Promise.resolve().then(function () { files[p] = b; return { ok: true }; }); },
        verifySize: function (p) { return Promise.resolve(files[p] ? files[p].length : 0); } };
      var ra = await M.runBackupsAsync(reg(3), okDeps);
      ok("runBackupsAsync happy: ok + count 3 + 3 files", ra.ok === true && ra.count === 3 && Object.keys(files).length === 3);
      var rb = await M.runBackupsAsync(reg(2), { versoFormat: fakeVF, tsLabel: "T",
        writeFile: function () { return Promise.resolve({ ok: false, error: "disk full" }); }, verifySize: function () { return Promise.resolve(9); } });
      ok("runBackupsAsync write fail: not ok", rb.ok === false && rb.count === 0);
      var rc = await M.runBackupsAsync(reg(1), { versoFormat: fakeVF, tsLabel: "T",
        writeFile: function () { return Promise.resolve({ ok: true }); }, verifySize: function () { return Promise.resolve(0); } });
      ok("runBackupsAsync verify fail (0 bytes): not ok", rc.ok === false);
    })());
  })();

  // WIRING: editor.js honours the guard at every save choke point; index.html loads it first.
  var ed = src("src/editor.js");
  ok("editor.js defines savesSuppressed via window.Migration", /function savesSuppressed\(\)\s*\{[\s\S]{0,160}window\.Migration[\s\S]{0,120}savesSuppressed\(\)/.test(ed));
  ok("saveRegistry early-returns when suppressed", /function saveRegistry\(r\)\s*\{\s*if \(savesSuppressed\(\)\) return false;/.test(ed));
  ok("scheduleSave early-returns when suppressed", /function scheduleSave\(\)\s*\{\s*if \(savesSuppressed\(\)\) return;/.test(ed));
  ok("flushSave early-returns when suppressed", /function flushSave\(\)\s*\{\s*if \(savesSuppressed\(\)\) return;/.test(ed));
  // WIRING: the guarded cutover orchestrator -- async, preconditions, backup-gate,
  // suppress, disk write+verify, flip-only-after-verify.
  ok("migrateToFileBackend is async", /async function migrateToFileBackend\(opts\)/.test(ed));
  ok("migrateToFileBackend requires the browser backend", /async function migrateToFileBackend\(opts\)[\s\S]{0,700}backend !== "browser"[\s\S]{0,80}return fail\("precondition"/.test(ed));
  ok("migrateToFileBackend requires the native store glue", /if \(!ns\) return fail\("precondition", "native file storage is not available/.test(ed));
  ok("migrateToFileBackend backup-gates before suppress", /window\.Migration\.runBackupsAsync\(src[\s\S]{0,700}bk\.count !== codes\.length[\s\S]{0,1900}window\.Migration\.suppress\(\)/.test(ed));
  ok("migrateToFileBackend writes then verifies from disk", /await putRegistry\(srcJson\)[\s\S]{0,400}await getRegistry\(\)[\s\S]{0,200}window\.Migration\.verifyRegistries\(srcJson, back\)/.test(ed));
  ok("migrateToFileBackend flips flag ONLY after verify passes", /if \(!v\.ok\) \{ window\.Migration\.resume\(\); return fail\("verify"[\s\S]{0,1500}setFlag\("file"\)/.test(ed));
  ok("migrateToFileBackend resumes saves on write/verify failure", /window\.Migration\.resume\(\); return fail\("write"[\s\S]{0,600}window\.Migration\.resume\(\); return fail\("verify"/.test(ed));
  // #18: the shared component library rides the SAME guarded cutover as the registry --
  // one flag flip must move both, or neither (never straddle backends).
  ok("migrateToFileBackend requires put/getLibrary too", /if \(!putLibrary \|\| !getLibrary\) return fail\("precondition", "native store is missing put\/getLibrary"\)/.test(ed));
  ok("migrateToFileBackend reads the browser library (optional source)", /libJson;[\s\S]{0,40}try \{ libJson = browserLibAdapter\.readLibrary\(\); \}/.test(ed));
  ok("migrateToFileBackend backs up the library before suppress", /if \(libJson\) \{[\s\S]{0,1200}window\.Migration\.suppress\(\)/.test(ed));
  ok("migrateToFileBackend writes+verifies the library after the registry, same suppression window", /window\.Migration\.verifyRegistries\(srcJson, back\)[\s\S]{0,600}if \(libJson\) \{[\s\S]{0,700}await putLibrary\(libJson\)[\s\S]{0,300}await getLibrary\(\)[\s\S]{0,300}window\.Migration\.verifyLibrary\(libJson, libBack\)/.test(ed));
  ok("migrateToFileBackend resumes saves on library write/verify failure too", /window\.Migration\.resume\(\); return fail\("write", "library:[\s\S]{0,600}window\.Migration\.resume\(\); return fail\("verify", "library:/.test(ed));
  ok("Editor exposes migrateToFileBackend", /migrateToFileBackend: migrateToFileBackend/.test(ed));
  // WIRING (#18): the library storage seam mirrors the registry's -- same pickStorageAdapter,
  // same flag, and loadLibrary/saveLibrary route through it (not a hardcoded localStorage call).
  ok("libraryAdapter uses the same pickStorageAdapter seam as the registry", /function libraryAdapter\(\) \{ return pickStorageAdapter\(storageBackend\(\), window\.__storageAdapter, browserLibraryAdapter\); \}/.test(ed));
  ok("loadLibrary reads via libraryAdapter, not a hardcoded localStorage call", /function loadLibrary\(\) \{[\s\S]{0,200}libraryAdapter\(\)\.readLibrary\(\)/.test(ed));
  ok("saveLibrary writes via libraryAdapter, not a hardcoded localStorage call", /function saveLibrary\(\) \{ try \{ libraryAdapter\(\)\.writeLibrary\(JSON\.stringify\(window\.LibraryStore\)\); \} catch \(e\) \{\} \}/.test(ed));
  // WIRING (Product Rail #1): ProductsStore mirrors the exact same seam pattern.
  ok("productsAdapter uses the same pickStorageAdapter seam as the registry/library", /function productsAdapter\(\) \{ return pickStorageAdapter\(storageBackend\(\), window\.__storageAdapter, browserProductsAdapter\); \}/.test(ed));
  ok("loadProducts reads via productsAdapter, not a hardcoded localStorage call", /function loadProducts\(\) \{[\s\S]{0,200}productsAdapter\(\)\.readProducts\(\)/.test(ed));
  ok("saveProducts writes via productsAdapter, not a hardcoded localStorage call", /function saveProducts\(\) \{ try \{ productsAdapter\(\)\.writeProducts\(JSON\.stringify\(window\.ProductsStore\)\); \} catch \(e\) \{\} \}/.test(ed));
  ok("store-native.js carries the same readProducts/writeProducts pair as readLibrary/writeLibrary", /readProducts: function \(\) \{ return productsCache; \}/.test(src("src/store-native.js")) && /writeProducts: function \(json\)/.test(src("src/store-native.js")));
  // WIRING (Product Rail): "Promote to Product" -- a per-course-only save-menu action
  // that writes ONLY doc.meta.productId/stage, never content, never a bulk variant.
  ok("'Promote to Product…' is wired into the save menu's action list", /action\("Promote to Product…", function \(\) \{ promoteToProductModal\(\); \}\)/.test(ed));
  ok("no bulk/batch variant exists anywhere (only ever operates on the single `doc`)", (ed.match(/promoteToProductModal\(/g) || []).length === 2); // definition + the one call site above
  var ptmStart = ed.indexOf("function promoteToProductModal()");
  ok("promoteToProductModal found", ptmStart !== -1);
  var ptmBody = ed.slice(ptmStart, ptmStart + 1900);
  ok("uses the canonical dsModalShell, not bespoke modal chrome", /var shell = dsModalShell\(\{/.test(ptmBody));
  ok("reuses the modalField + dsSelect pattern (Find & Replace's precedent), not a new control", /modalField\(box, "Product"\)[\s\S]{0,200}dsSelect\(pOpts, chosen/.test(ptmBody) && /modalField\(box, "Format"\)[\s\S]{0,200}dsSelect\(PRODUCT_STAGE_OPTS, stage/.test(ptmBody));
  ok("writes ONLY doc.meta via tagDocProductStage, then persists -- no content field touched", /pushHistory\(\);\s*\n\s*tagDocProductStage\(doc, pid, stage\);\s*\n\s*saveRegistry\(registry\);/.test(ptmBody));
  ok("A1: onPrimary dismisses the modal (shell.modal.close) + refreshes the product context (mountProductPicker)", /saveRegistry\(registry\);\s*\n\s*shell\.modal\.close\(\);\s*\n\s*mountProductPicker\(\);/.test(ptmBody));
  ok("'+ Create a new Product…' path calls createProduct, not a raw ProductsStore write", /if \(chosen === NEW_KEY\) \{[\s\S]{0,150}pid = createProduct\(name\)\.id;/.test(ptmBody));
  // WIRING: the guarded menu item -- DS confirmModal, registered ONLY with the native store.
  ok("migrate prompt uses the DS confirmModal (not bespoke chrome)", /function migrateToFileBackendPrompt\(\)[\s\S]{0,200}confirmModal\("Migrate to file storage"/.test(ed));
  ok("migrate button registered only when __nativeStore present", /if \(window\.__nativeStore\) window\.Editor\.registerPipelineButton\("Migrate to file storage \(beta\)", migrateToFileBackendPrompt/.test(ed));
  // WIRING: the Swift bridge grew the ops the native store glue posts.
  var swift = src("desktop/AuthoringTool.swift");
  ["storePutRegistry", "storeGetRegistry", "storePutLibrary", "storeGetLibrary", "storePutProducts", "storePutBackupB64", "storeFileSize", "storeReload"].forEach(function (op) {
    ok("Swift handleBackup handles op " + op, swift.indexOf('op == "' + op + '"') !== -1);
  });
  ok("Swift injects the on-disk registry at document-start", /addUserScript\(registryInjectionScript\(\)\)/.test(swift) && /window\.__versoDiskRegistryB64/.test(swift));
  ok("Swift injects the on-disk library at document-start (#18)", /addUserScript\(libraryInjectionScript\(\)\)/.test(swift) && /window\.__versoDiskLibraryB64/.test(swift));
  // REGRESSION (Product Rail data-loss bug, found via James's live testing): writeProducts
  // posts storePutProducts, but the Swift shell never grew a case for it (nor a boot
  // injection) -- every Product/topic was silently non-durable in the real app. Guards both halves.
  ok("Swift injects the on-disk products store at document-start", /addUserScript\(productsInjectionScript\(\)\)/.test(swift) && /window\.__versoDiskProductsB64/.test(swift));
  ok("Swift reload refreshes the registry injection", /@objc func reload\(\) \{ refreshRegistryInjection\(\)/.test(swift));
  ok("Swift refreshRegistryInjection rebuilds registry, library, AND products scripts", /func refreshRegistryInjection\(\) \{[\s\S]{0,300}addUserScript\(registryInjectionScript\(\)\)[\s\S]{0,100}addUserScript\(libraryInjectionScript\(\)\)[\s\S]{0,100}addUserScript\(productsInjectionScript\(\)\)/.test(swift));
  ok("Swift storePutLibrary writes library.json and refreshes injections", /op == "storePutLibrary"[\s\S]{0,600}library\.json[\s\S]{0,300}refreshRegistryInjection\(\)/.test(swift));
  ok("Swift storePutProducts writes products.json and refreshes injections", /op == "storePutProducts"[\s\S]{0,600}products\.json[\s\S]{0,300}refreshRegistryInjection\(\)/.test(swift));
  ok("Swift storePath rejects absolute / parent-escape paths", /func storePath[\s\S]{0,160}hasPrefix\("\/"\)[\s\S]{0,40}contains\("\.\."\)/.test(swift));
  // REGRESSION: editor.js's __versoBackupReply must CHAIN store-native's, not clobber it.
  ok("editor.js chains a prior __versoBackupReply owner", /__prevBackupReply = window\.__versoBackupReply[\s\S]{0,320}typeof __prevBackupReply === "function"\) __prevBackupReply\(id, result\)/.test(ed));
  var html = src("index.html");
  ok("index.html loads migration.js before editor.js", html.indexOf("src/migration.js") !== -1 && html.indexOf("src/migration.js") < html.indexOf("src/editor.js"));
  ok("index.html loads store-native.js before editor.js", html.indexOf("src/store-native.js") !== -1 && html.indexOf("src/store-native.js") < html.indexOf("src/editor.js"));

  // ---- store-native.js: inert without bridge; confirmed writes with it ---
  (function () {
    // No bridge -> the adapter is never installed (browser backend only).
    var w1 = {};
    new Function("window", src("src/store-native.js"))(w1);
    ok("store-native inert without bridge (no __storageAdapter)", !w1.__storageAdapter);
    // With a fake bridge -> a 'file' adapter that posts storePutRegistry + confirms.
    var posted = [];
    var w2 = {
      webkit: { messageHandlers: { versoBackup: { postMessage: function (m) { posted.push(m); } } } },
      __versoDiskRegistryB64: null,
      TextDecoder: TextDecoder, TextEncoder: TextEncoder, atob: function (b) { return Buffer.from(b, "base64").toString("binary"); }, btoa: function (s) { return Buffer.from(s, "binary").toString("base64"); }
    };
    new Function("window", src("src/store-native.js"))(w2);
    ok("store-native installs a 'file' adapter with a bridge", !!w2.__storageAdapter && w2.__storageAdapter.name === "file");
    // REGRESSION (real load order): editor.js installs its OWN __versoBackupReply AFTER
    // store-native. It MUST chain, not clobber, or every native-store reply is lost and the
    // #69 migration hangs. Simulate editor's chaining wrapper; all replies below route through it.
    (function installEditorReplyChain() {
      var editorPending = {}; var prev = w2.__versoBackupReply;
      w2.__versoBackupReply = function (id, r) { var p = editorPending[id]; if (p) { delete editorPending[id]; p(r); return; } if (typeof prev === "function") prev(id, r); };
    })();
    var wr = w2.__storageAdapter.writeRegistry('{"C-1":{}}');
    ok("writeRegistry returns ok + caches synchronously", wr.ok === true && w2.__storageAdapter.readRegistry() === '{"C-1":{}}');
    ok("writeRegistry posts storePutRegistry with a reqId", posted.length === 1 && posted[0].op === "storePutRegistry" && typeof posted[0].reqId === "string");
    // #18: the library gets the identical adapter shape, on a separate op/cache.
    var wl = w2.__storageAdapter.writeLibrary('{"components":{"c1":{}}}');
    ok("writeLibrary returns ok + caches synchronously", wl.ok === true && w2.__storageAdapter.readLibrary() === '{"components":{"c1":{}}}');
    ok("writeLibrary posts storePutLibrary with a reqId, separate from the registry op", posted.length === 2 && posted[1].op === "storePutLibrary" && typeof posted[1].reqId === "string" && posted[1].reqId !== posted[0].reqId);
    ok("registry cache untouched by a library write", w2.__storageAdapter.readRegistry() === '{"C-1":{}}');
    // A failed disk reply surfaces via Editor.reportSaveFailure (not lost fire-and-forget).
    var failMsg = null; w2.Editor = { reportSaveFailure: function (m) { failMsg = m; } };
    w2.__versoBackupReply(posted[0].reqId, { ok: false, error: "disk full" });
    ok("failed disk write surfaces through reportSaveFailure", !!failMsg && /NOT durably saved/.test(failMsg));
    // A prior __versoBackupReply owner is chained, not clobbered.
    var w3 = {
      webkit: { messageHandlers: { versoBackup: { postMessage: function () {} } } },
      __versoBackupReply: function (id, o) { w3.__seen = id; },
      TextDecoder: TextDecoder, TextEncoder: TextEncoder, atob: w2.atob, btoa: w2.btoa
    };
    new Function("window", src("src/store-native.js"))(w3);
    w3.__versoBackupReply("someOtherOp:1", { ok: true });
    ok("store-native chains a prior __versoBackupReply owner", w3.__seen === "someOtherOp:1");

    // __nativeStore async glue: the live deps for Editor.migrateToFileBackend. Driven
    // LAST so its request()->reply posts don't perturb the sync writeRegistry checks above.
    var ns = w2.__nativeStore;
    ok("store-native exposes __nativeStore with the live deps", !!ns && ["putRegistry", "getRegistry", "putLibrary", "getLibrary", "writeFile", "verifySize", "reload", "tsLabel"].every(function (k) { return typeof ns[k] === "function"; }));
    ok("tsLabel is a filesystem-safe timestamp", /^\d{8}-\d{6}$/.test(ns.tsLabel()));
    __async.push((async function () {
      var pv = ns.verifySize("backups/pre-cutover-T/C-1.verso");
      var lv = posted[posted.length - 1];
      ok("verifySize posts storeFileSize with a store-relative path", lv.op === "storeFileSize" && lv.path === "backups/pre-cutover-T/C-1.verso");
      w2.__versoBackupReply(lv.reqId, { ok: true, size: 42 });
      ok("verifySize resolves the on-disk size", (await pv) === 42);
      var pw = ns.writeFile("backups/pre-cutover-T/C-1.verso", new Uint8Array([1, 2, 3, 250]));
      var lw = posted[posted.length - 1];
      ok("writeFile posts storePutBackupB64 with base64 bytes", lw.op === "storePutBackupB64" && typeof lw.b64 === "string" && lw.b64.length > 0);
      w2.__versoBackupReply(lw.reqId, { ok: true, size: 4 });
      ok("writeFile resolves { ok, size }", (function (r) { return r.ok === true && r.size === 4; })(await pw));
      var pg = ns.getRegistry();
      var lg = posted[posted.length - 1];
      w2.__versoBackupReply(lg.reqId, { ok: true, text: '{"A":{}}' });
      ok("getRegistry resolves the on-disk text", (await pg) === '{"A":{}}');
      // #18: same async glue, targeting the library ops.
      var ppl = ns.putLibrary('{"components":{"c1":{}}}');
      var lpl = posted[posted.length - 1];
      ok("putLibrary posts storePutLibrary", lpl.op === "storePutLibrary" && lpl.text === '{"components":{"c1":{}}}');
      w2.__versoBackupReply(lpl.reqId, { ok: true, path: "/x/library.json" });
      ok("putLibrary resolves the confirmation", (await ppl).ok === true);
      var pgl = ns.getLibrary();
      var lgl = posted[posted.length - 1];
      ok("getLibrary posts storeGetLibrary", lgl.op === "storeGetLibrary");
      w2.__versoBackupReply(lgl.reqId, { ok: true, text: '{"components":{"c1":{}}}' });
      ok("getLibrary resolves the on-disk text", (await pgl) === '{"components":{"c1":{}}}');
    })());
  })();
})();

// ---- #19: component-library stable-id master snapshot model ---------------
section("#19 stable-id master snapshot");
(function () {
  var etxt = src("src/editor.js");

  // 1. CAPTURE mints ids ONCE: saveBlockAsComponent's template is remintIds(clone(block)).
  // From that moment the ids are the component's permanent identity.
  ok("saveBlockAsComponent mints fresh ids once at capture", /comps\[id\] = \{ name: name, kind: "composed", template: remintIds\(clone\(block\)\) \};/.test(etxt));

  // 2. PRESERVE discipline: promoting to the shared library and detaching a local copy
  // must NEVER remint -- a regex catches a future edit that adds a stray remintIds()
  // call to either handler, which would silently break every existing instance's
  // ability to key an override against the master's (now-drifted) block ids.
  var copyIdx = etxt.indexOf("getComponents()[k] = clone(comp); saveRegistry(registry); mount();");
  ok("'Copy to course' handler found", copyIdx !== -1);
  ok("'Copy to course' preserves ids (no remint)", copyIdx !== -1 && etxt.slice(copyIdx - 20, copyIdx + 80).indexOf("remintIds") === -1);
  var saveIdx = etxt.indexOf("var promoted = clone(doc.components[selectedKey]);");
  ok("'Save to library' handler found", saveIdx !== -1);
  ok("'Save to library' preserves ids (no remint)", saveIdx !== -1 && etxt.slice(saveIdx - 20, saveIdx + 220).indexOf("remintIds") === -1);
  // Product Rail: the SAME handler is the sole content-mutation site, so it's where both
  // the version stamp and the owner-Product tag stamp bump/land -- both BEFORE the master
  // lands in the shared store.
  var psaveBody = etxt.slice(saveIdx, saveIdx + 700);
  ok("'Save to library' stamps the version BEFORE the master lands in the shared store", /stampMasterVersion\(promoted, Date\.now\(\)\)[\s\S]{0,600}window\.LibraryStore\.components\[selectedKey\] = promoted;/.test(psaveBody));
  ok("'Save to library' also stamps the owner-Product tag BEFORE the master lands", /stampOwnerProductTag\(promoted, doc\.meta && doc\.meta\.productId\)[\s\S]{0,300}window\.LibraryStore\.components\[selectedKey\] = promoted;/.test(psaveBody));

  // 3. The contract is documented at remintIds' own definition, so #20/#21/#24 don't
  // add a 5th call site that touches library-resident content.
  ok("remintIds documents the #19 library-preservation contract", /NEVER call remintIds on content already\s*\n\s*\/\/ resident in doc\.components or LibraryStore\.components/.test(etxt));

  // 4. ROUND-TRIP STABILITY (JSON save/load, e.g. through the #18 storage seam): a
  // captured component's nested block ids survive byte-identical.
  var comp = { name: "Probe", kind: "composed", template: { id: "b_1", type: "frame", children: [{ id: "b_2", type: "paragraph" }, { id: "b_3", type: "columns", columns: [[{ id: "b_4", type: "image" }]] }] } };
  var savedJson = JSON.stringify({ components: { probe: comp } });
  var loaded = JSON.parse(savedJson);
  ok("library JSON save/load preserves a master's ids byte-identical", JSON.stringify(loaded.components.probe) === JSON.stringify(comp));
  ok("nested child id specifically unchanged", loaded.components.probe.template.children[0].id === "b_2");
  ok("nested column-child id specifically unchanged", loaded.components.probe.template.children[1].columns[0][0].id === "b_4");
  // a second round-trip (save -> load -> save -> load) must be a no-op (idempotent).
  var loaded2 = JSON.parse(JSON.stringify(loaded));
  ok("a second save/load cycle is idempotent", JSON.stringify(loaded2) === JSON.stringify(loaded));

  // 5. .verso EXPORT/IMPORT STABILITY: a doc-local composed component's nested ids
  // survive VersoFormat.buildPackage/readPackage untouched (no id processing there).
  var vfWin = {};
  new Function("window", src("src/verso-format.js"))(vfWin);
  var VF = vfWin.VersoFormat;
  if (!VF) { ok("VersoFormat loaded for #19 round-trip", false); }
  else {
    var doc = { meta: { code: "C-1", title: "Probe course" }, pages: [{ blocks: [] }], components: { probe: comp } };
    var pkg = VF.buildPackage(doc, {}, {});
    var back = VF.readPackage(pkg);
    ok(".verso round-trip preserves a doc component's nested ids byte-identical", JSON.stringify(back.doc.components) === JSON.stringify(doc.components));
  }
})();

// ---- YY: asset walk helpers + store --------------------------------------
section("YY asset-seam");
(function () {
  var rtxt = src("src/render.js");
  var block = rtxt.slice(rtxt.indexOf("var ASSET_RE"), rtxt.lastIndexOf("})();"));
  var rw = {};
  new Function("window", block)(rw);
  var doc = {
    chrome: { header: { logo: "asset:LOGO" } },
    pages: [{ blocks: [
      { type: "image", src: "asset:IMG1", alt: "keep" },
      { type: "group", children: [{ src: "asset:IMG2" }] },
      { type: "columns", columns: [[{ srcLight: "asset:L", srcDark: "asset:D" }]] },
      { hotspots: [{ screen: "asset:HS" }, { screen: "https://x/a.png" }] },
      { localVideo: "asset:VID" }
    ] }]
  };
  var restore = rw.resolveMedia(doc, function (id) { return "URL:" + id; });
  ok("resolve logo", doc.chrome.header.logo === "URL:LOGO");
  ok("resolve deep child", doc.pages[0].blocks[1].children[0].src === "URL:IMG2");
  ok("resolve columns", doc.pages[0].blocks[2].columns[0][0].srcDark === "URL:D");
  ok("resolve hotspot", doc.pages[0].blocks[3].hotspots[0].screen === "URL:HS");
  ok("http untouched", doc.pages[0].blocks[3].hotspots[1].screen === "https://x/a.png");
  restore();
  ok("restore refs", doc.chrome.header.logo === "asset:LOGO" && doc.pages[0].blocks[4].localVideo === "asset:VID");
  ok("collectAssetRefs", rw.collectAssetRefs(doc).sort().join(",") === "D,HS,IMG1,IMG2,L,LOGO,VID");
  var md = { pages: [{ blocks: [{ src: "data:image/png;base64,AAA" }, { src: "data:img,FAILME" }, { src: "asset:x" }] }] };
  var mr = rw.migrateDocMedia(md, function (d) { return d.indexOf("FAILME") !== -1 ? null : "hoisted"; });
  ok("migrate count", mr.migrated === 1 && mr.failed === 1);
  ok("migrate success->ref", md.pages[0].blocks[0].src === "asset:hoisted");
  ok("migrate fail keeps data:", md.pages[0].blocks[1].src === "data:img,FAILME");

  // Hotspot tour SOURCE videos (author-time harvest scratch) must never ship: a `sources`
  // container is SKIPPED by eachMediaSlot, so resolveMedia (used by BOTH the editor pre-pass
  // and the export bake) leaves it untouched -> no media/<id> file, no inline base64 in export.
  // But collectAssetRefs (garbage-collection) MUST still keep it, so a persisted source survives
  // the unload mark-sweep and is there next time the tour builder opens.
  var sdoc = { pages: [{ blocks: [
    { type: "hotspot", screens: [{ visual: "asset:SCR" }], sources: [{ id: "src1", visual: "asset:SRCVID" }] }
  ] }] };
  var sres = [];
  var srestore = rw.resolveMedia(sdoc, function (id) { sres.push(id); return "URL:" + id; });
  ok("source excluded from resolve (render+export)", sres.indexOf("SRCVID") === -1 && sres.indexOf("SCR") !== -1);
  ok("source ref left intact by resolve", sdoc.pages[0].blocks[0].sources[0].visual === "asset:SRCVID");
  srestore();
  ok("source KEPT for GC (persists across sessions)", rw.collectAssetRefs(sdoc).sort().join(",") === "SCR,SRCVID");

  // Bulk "Purge all sources" (editor Advanced section) deletes block.sources wholesale.
  // Once gone, collectAssetRefs must stop keeping the purged ids -- same GC contract as the
  // per-source Remove above, but for every source on the board at once.
  var pgdoc = { pages: [{ blocks: [
    { type: "hotspot", screens: [{ visual: "asset:SCR" }], sources: [{ id: "src1", visual: "asset:SRCVID" }, { id: "src2", visual: "asset:SRCVID2" }] }
  ] }] };
  ok("purge: sources present before purge", rw.collectAssetRefs(pgdoc).sort().join(",") === "SCR,SRCVID,SRCVID2");
  delete pgdoc.pages[0].blocks[0].sources;
  ok("purge: sources gone from GC refs after purge", rw.collectAssetRefs(pgdoc).join(",") === "SCR");

  // A harvested screen carries provenance `source:{id,t}` (which source frame it came from).
  // That's inert data (id string + number) — it must add NO asset ref (no export/GC impact);
  // only the screen's own visual counts.
  var pdoc = { pages: [{ blocks: [{ type: "hotspot", screens: [{ visual: "asset:PV", source: { id: "src-x", t: 5 } }] }] }] };
  ok("harvest provenance source:{id,t} is inert (no asset ref)", rw.collectAssetRefs(pdoc).join(",") === "PV");

  // embed-html hoist (quota/data-loss reroute): raw htmlEmbed markup must leave
  // the doc JSON as an "asset:<id>" ref; already-ref/URL html + non-embeds untouched;
  // a failed put is left raw (non-destructive); round-trips back to raw via resolveEmbedHtml.
  var ed = { pages: [{ blocks: [
    { type: "htmlEmbed", html: "<b>hi</b>" },
    { type: "htmlEmbed", html: "asset:existing" },
    { type: "htmlEmbed", html: "https://x/a.html" },
    { type: "htmlEmbed", html: "<b>FAILME</b>" },
    { type: "text", html: "<p>not an embed</p>" }
  ] }] };
  var puts = [];
  var er = rw.migrateDocEmbedHtml(ed, function (d) { puts.push(d); return d.indexOf("FAILME") !== -1 ? null : "hoisted"; });
  ok("embed hoist count", er.migrated === 1 && er.failed === 1);
  ok("embed raw -> asset ref", ed.pages[0].blocks[0].html === "asset:hoisted");
  ok("embed put got data:text/html", puts[0].slice(0, 15) === "data:text/html;");
  ok("embed asset ref untouched", ed.pages[0].blocks[1].html === "asset:existing");
  ok("embed url untouched", ed.pages[0].blocks[2].html === "https://x/a.html");
  ok("embed fail keeps raw", ed.pages[0].blocks[3].html === "<b>FAILME</b>");
  ok("non-embed html untouched", ed.pages[0].blocks[4].html === "<p>not an embed</p>");
  ok("embed hoist round-trips", decodeURIComponent(puts[0].slice(puts[0].indexOf(",") + 1)) === "<b>hi</b>");

  // store
  var ptxt = src("src/persist.js");
  var pe = ptxt.indexOf("placeholder: PLACEHOLDER"); pe = ptxt.indexOf("};", pe) + 2;
  var pblock = ptxt.slice(ptxt.indexOf("var ASSET_KEY"), pe);
  var lsStore = {}, failNext = false;
  var fakeLS = { getItem: function (k) { return k in lsStore ? lsStore[k] : null; }, setItem: function (k, v) { if (failNext) { var e = new Error("full"); e.name = "QuotaExceededError"; throw e; } lsStore[k] = v; } };
  var n = 0, fakeURL = { createObjectURL: function () { return "blob:" + (++n); }, revokeObjectURL: function () {} };
  var pw = { Editor: { reportSaveFailure: function () {} }, console: console };
  new Function("window", "localStorage", "URL", "Blob", "atob", pblock)(pw, fakeLS, fakeURL, function () {}, function (s) { return Buffer.from(s, "base64").toString("binary"); });
  var AS = pw.AssetStore;
  var id = AS.put("data:image/png;base64,AAAA", { mime: "image/png" });
  ok("put id + dedupe", !!id && AS.put("data:image/png;base64,AAAA", {}) === id);
  var svg = AS.put("data:image/svg+xml;utf8,<svg/>", { mime: "image/svg+xml" });
  ok("svg url -> data:", AS.url(svg).slice(0, 5) === "data:");
  ok("raster url -> blob:", AS.url(id).slice(0, 5) === "blob:");
  failNext = true;
  var realErr = console.error; console.error = function () {}; // expected quota log
  ok("quota put -> null", AS.put("data:image/png;base64,BBBB", {}) === null);
  console.error = realErr;
  failNext = false;
  AS.sweep([svg]);
  ok("sweep removes unref", !AS.has(id) && AS.has(svg));
})();

// ---- tour source MediaTransport: pure time/mark helpers ------------------
section("tour media transport (pure)");
(function () {
  var etxt = src("src/editor.js");
  var a = etxt.indexOf("/* __TOUR_MEDIA_PURE__ start");
  var b = etxt.indexOf("/* __TOUR_MEDIA_PURE__ end");
  if (a < 0 || b < 0) { ok("tour media pure block present", false); return; }
  var block = etxt.slice(etxt.indexOf("\n", a) + 1, b);
  var api = new Function(block + "; return { fmt: tourFormatTime, mark: tourApplyMark, crop: tourCropRect, segReady: tourSegReady, speedField: tourSpeedField, applyCut: tourApplyCut, mergeCuts: tourMergeCuts, clipCuts: tourClipCutsToBounds, keptRanges: tourKeptRanges, netLength: tourNetLength };")();
  ok("fmt 0 -> 0:00", api.fmt(0) === "0:00");
  ok("fmt 65 -> 1:05", api.fmt(65) === "1:05");
  ok("fmt neg -> 0:00", api.fmt(-5) === "0:00");
  var r1 = api.mark("in", 3, {});
  ok("mark in", r1.in === 3 && r1.out == null);
  var r2 = api.mark("out", 10, r1);
  ok("mark out keeps valid in", r2.in === 3 && r2.out === 10);
  ok("out<=in drops the in", (function () { var r = api.mark("out", 2, r2); return r.in == null && r.out === 2; })());
  ok("in>=out drops the out", (function () { var r = api.mark("in", 20, { in: 3, out: 10 }); return r.in === 20 && r.out == null; })());
  // crop rect: no crop = full frame; a normalised crop maps to source-px + output dims;
  // clamped in-bounds; all harvests from one crop share the same output W x H.
  ok("cropRect null = full frame", (function () { var r = api.crop(null, 1920, 1080); return r.sx === 0 && r.sy === 0 && r.sw === 1920 && r.sh === 1080 && r.w === 1920 && r.h === 1080; })());
  ok("cropRect half", (function () { var r = api.crop({ x: 0.25, y: 0.5, w: 0.5, h: 0.5 }, 1920, 1080); return r.sx === 480 && r.sy === 540 && r.w === 960 && r.h === 540; })());
  ok("cropRect clamps out-of-bounds", (function () { var r = api.crop({ x: 0.8, y: 0, w: 0.5, h: 1 }, 1000, 1000); return r.sx === 800 && r.w === 200; })());
  ok("cropRect two harvests same size", (function () { var a = api.crop({ x: 0.1, y: 0.1, w: 0.3, h: 0.3 }, 1280, 720), b = api.crop({ x: 0.1, y: 0.1, w: 0.3, h: 0.3 }, 1280, 720); return a.w === b.w && a.h === b.h; })());
  // segment gate: needs both ends marked and in < out
  ok("segReady both + in<out", api.segReady(2, 8) === true);
  ok("segReady needs both", api.segReady(2, null) === false && api.segReady(null, 8) === false);
  ok("segReady rejects out<=in", api.segReady(8, 2) === false && api.segReady(5, 5) === false);
  // speed preset -> provenance field: 1x (or junk) = default = no field; other rates persist the number
  ok("speedField 1x -> null (default)", api.speedField(1) === null && api.speedField("1") === null);
  ok("speedField omits undefined/0/NaN", api.speedField(undefined) === null && api.speedField(0) === null && api.speedField("x") === null);
  ok("speedField keeps 0.5 / 2 / 1.25", api.speedField("0.5") === 0.5 && api.speedField(2) === 2 && api.speedField("1.25") === 1.25);
})();

// ---- ripple cuts: T1 pure model + logic ----------------------------------
section("tour ripple cuts (pure)");
(function () {
  var etxt = src("src/editor.js");
  var a = etxt.indexOf("/* __TOUR_MEDIA_PURE__ start"), b = etxt.indexOf("/* __TOUR_MEDIA_PURE__ end");
  var block = etxt.slice(etxt.indexOf("\n", a) + 1, b);
  var api = new Function(block + "; return { applyCut: tourApplyCut, mergeCuts: tourMergeCuts, clipCuts: tourClipCutsToBounds, keptRanges: tourKeptRanges, netLength: tourNetLength, segReady: tourSegReady };")();
  // applyCut: commit a pending cut-in + playhead into an ordered removed range; reject crossings
  ok("applyCut forms ordered cut", (function () { var c = api.applyCut(3, 8); return c && c.start === 3 && c.end === 8; })());
  ok("applyCut rejects out<=in", api.applyCut(8, 3) === null && api.applyCut(5, 5) === null);
  ok("applyCut rejects null end", api.applyCut(null, 8) === null && api.applyCut(3, null) === null);
  // mergeCuts: sort + merge overlap AND adjacency; drop zero-length
  ok("mergeCuts sorts ascending", (function () { var m = api.mergeCuts([{ start: 8, end: 10 }, { start: 2, end: 4 }]); return m.length === 2 && m[0].start === 2 && m[1].start === 8; })());
  ok("mergeCuts merges overlap", (function () { var m = api.mergeCuts([{ start: 2, end: 6 }, { start: 4, end: 9 }]); return m.length === 1 && m[0].start === 2 && m[0].end === 9; })());
  ok("mergeCuts merges adjacency", (function () { var m = api.mergeCuts([{ start: 2, end: 5 }, { start: 5, end: 8 }]); return m.length === 1 && m[0].end === 8; })());
  ok("mergeCuts drops zero-length", api.mergeCuts([{ start: 3, end: 3 }, { start: 4, end: 4 }]).length === 0);
  // clipCutsToBounds: drop-outside + trim-straddling; empty without valid bounds
  ok("clipCuts drops outside", api.clipCuts([{ start: 20, end: 25 }], 5, 15).length === 0);
  ok("clipCuts trims straddle", (function () { var c = api.clipCuts([{ start: 3, end: 8 }], 5, 15); return c.length === 1 && c[0].start === 5 && c[0].end === 8; })());
  ok("clipCuts empty on bad bounds", api.clipCuts([{ start: 3, end: 8 }], null, 15).length === 0 && api.clipCuts([{ start: 3, end: 8 }], 15, 5).length === 0);
  // keptRanges: decompose in->out minus cuts into surviving pieces
  ok("keptRanges no cuts = whole", (function () { var k = api.keptRanges(0, 10, []); return k.length === 1 && k[0].in === 0 && k[0].out === 10; })());
  ok("keptRanges middle cut -> two pieces", (function () { var k = api.keptRanges(0, 10, [{ start: 3, end: 6 }]); return k.length === 2 && k[0].in === 0 && k[0].out === 3 && k[1].in === 6 && k[1].out === 10; })());
  ok("keptRanges cut on in pulls bound", (function () { var k = api.keptRanges(0, 10, [{ start: 0, end: 3 }]); return k.length === 1 && k[0].in === 3 && k[0].out === 10; })());
  ok("keptRanges swallow-all -> empty", api.keptRanges(0, 10, [{ start: 0, end: 10 }]).length === 0);
  // netLength: sum of kept ranges
  ok("netLength subtracts cuts", api.netLength(0, 10, [{ start: 3, end: 6 }]) === 7);
  ok("netLength no cuts = span", api.netLength(2, 8, []) === 6);
  ok("netLength swallow-all = 0", api.netLength(0, 10, [{ start: 0, end: 10 }]) === 0);
  // segReady extended: net kept length > 0 (backward-compatible with no cuts arg)
  ok("segReady harmless cut still ready", api.segReady(0, 10, [{ start: 3, end: 6 }]) === true);
  ok("segReady swallow-all not ready", api.segReady(0, 10, [{ start: 0, end: 10 }]) === false);
  ok("segReady no-cuts arg still ready", api.segReady(2, 8) === true);
})();

