// ---- Mojibake repair: ftfy-style legacy-decode round-trip (render.js) -------------
section("mojibake repair");
(function () {
  var rtxt = src("src/render.js");
  var etxt = src("src/editor.js");
  // extract the self-contained repair block from render.js (marker-delimited) and expose
  // its charset tables so the test can FORWARD-encode true mojibake (intended text ->
  // UTF-8 bytes -> legacy charset) and assert repair() is the exact inverse. This can't
  // drift from a hand-transcribed table (the old fixed table had a wrong ellipsis byte).
  var body = rtxt.slice(rtxt.indexOf("// [MOJIBAKE-REPAIR-START]"), rtxt.indexOf("// [MOJIBAKE-REPAIR-END]"));
  var M = new Function(body + "\nreturn { repairMojibake: repairMojibake, MACROMAN: MACROMAN, WIN1252: WIN1252 };")();
  var repair = M.repairMojibake;
  function utf8Bytes(s) { // JS string -> UTF-8 byte array
    var b = [], u = unescape(encodeURIComponent(s));
    for (var i = 0; i < u.length; i++) b.push(u.charCodeAt(i));
    return b;
  }
  function garble(intended, table) { // what a UTF-8-as-<table> bad decode produces
    var bytes = utf8Bytes(intended), out = "";
    for (var i = 0; i < bytes.length; i++) {
      var by = bytes[i];
      if (by < 0x80) out += String.fromCharCode(by);
      else { var cp = table[by - 0x80]; if (cp == null) return null; out += String.fromCharCode(cp); }
    }
    return out;
  }
  function roundtrips(intended, table) { var g = garble(intended, table); return g != null && g !== intended && repair(g) === intended; }
  // Mac-Roman (James's CONFIRMED sample: UTF-8 bytes decoded as Mac OS Roman)
  ok("Mac-Roman em dash — round-trips", roundtrips("a — b", M.MACROMAN));
  ok("Mac-Roman en dash – round-trips", roundtrips("x – y", M.MACROMAN));
  ok("Mac-Roman curly quotes “ ” ’ round-trip", roundtrips("“it’s” fine", M.MACROMAN));
  ok("Mac-Roman ellipsis … + bullet • round-trip", roundtrips("wait… • item", M.MACROMAN));
  ok("Mac-Roman arrows ↑ ↓ round-trip", roundtrips("go ↑ or ↓", M.MACROMAN));
  ok("Mac-Roman accented word café round-trips", roundtrips("un café", M.MACROMAN));
  // Windows-1252 (follow-up b -- landed in the SAME pass)
  ok("Win-1252 accented café round-trips", roundtrips("un café", M.WIN1252));
  ok("Win-1252 em dash — round-trips", roundtrips("a — b", M.WIN1252));
  // NB: U+201D (”) maps to byte 0x9D which is UNDEFINED in Win-1252, so it can't round-trip
  // through that charset (Mac-Roman covers it); use chars in defined Win-1252 slots here.
  ok("Win-1252 left-quote + apostrophe round-trip", roundtrips("“it’s fine", M.WIN1252));
  ok("Win-1252 euro € round-trips", roundtrips("costs €5", M.WIN1252));
  // Safety: correctly-encoded text is never corrupted (a lone high byte = invalid UTF-8)
  ok("plain ASCII untouched (no false positives)", repair("plain, ascii - text") === "plain, ascii - text");
  ok("legit accents + dashes untouched", repair("Hello — café naïve ½ résumé") === "Hello — café naïve ½ résumé");
  ok("empty / non-string pass through", repair("") === "" && repair(42) === 42 && repair(null) === null);
  ok("idempotent (already-clean text is a no-op)", repair(repair(garble("a — b", M.MACROMAN))) === "a — b");
  ok("exposed as window.__repairMojibake", /window\.__repairMojibake = repairMojibake;/.test(rtxt));
  // editor.js now delegates to the single render.js implementation (no fixed table)
  ok("editor repairMojibake delegates to window.__repairMojibake", /function repairMojibake\(s\) \{\s*return \(typeof s === "string" && typeof window\.__repairMojibake === "function"\) \? window\.__repairMojibake\(s\) : s;/.test(etxt));
  ok("editor sanitizeText still folds the repair in (via sanitizeDeep on load)", /function sanitizeText\(s\) \{ return typeof s === "string" \? repairMojibake\(s\)\.replace\(INVISIBLE_RE, ""\)/.test(etxt));
})();

// ---- htmlEmbed: bundled-src (block.src) interactions are decoded + repaired too ----
section("mojibake repair — bundled-src path");
(function () {
  var rtxt = src("src/render.js");
  // wiring: block.src is resolved to raw markup + mojibake-repaired, then rendered via
  // srcdoc (so it gets the theme shim + repair), falling back to src= only if undecodable.
  ok("block.src decoded via resolveEmbedHtml + repairMojibake", /var __srcHtml = block\.src \? repairMojibake\(resolveEmbedHtml\(block\.src\)\) : "";/.test(rtxt));
  ok("block.html path also repaired", /var __embedHtml = repairMojibake\(resolveEmbedHtml\(block\.html\)\);/.test(rtxt));
  ok("either markup renders via srcdoc with the theme shim", /if \(__html\) frame\.setAttribute\("srcdoc", __html \+ "\\n<script>" \+ EMBED_THEME_SHIM/.test(rtxt));
  ok("falls back to plain src= only when undecodable", /else frame\.setAttribute\("src", assetSrc\(block\.src\)\);/.test(rtxt));
  // functional: a bundled data:text/html file carrying Mac-Roman mojibake, decoded exactly
  // as resolveEmbedHtml does, then repaired -> clean markup ready for srcdoc.
  var body = rtxt.slice(rtxt.indexOf("// [MOJIBAKE-REPAIR-START]"), rtxt.indexOf("// [MOJIBAKE-REPAIR-END]"));
  var repair = new Function(body + "\nreturn repairMojibake;")();
  var reBody = rtxt.slice(rtxt.indexOf("function resolveEmbedHtml"), rtxt.indexOf("window.resolveEmbedHtml"));
  var resolveEmbedHtml = new Function("var window={};" + reBody + "\nreturn resolveEmbedHtml;")();
  function utf8Bytes(s) { var b = [], u = unescape(encodeURIComponent(s)); for (var i = 0; i < u.length; i++) b.push(u.charCodeAt(i)); return b; }
  var MAC = new Function(body + "\nreturn MACROMAN;")();
  function garble(s) { var by = utf8Bytes(s), o = ""; for (var i = 0; i < by.length; i++) o += by[i] < 0x80 ? String.fromCharCode(by[i]) : String.fromCharCode(MAC[by[i] - 0x80]); return o; }
  var mojibakeMarkup = garble("<p>press — then • go</p>");
  var dataUrl = "data:text/html," + encodeURIComponent(mojibakeMarkup); // what a bundled asset resolves to
  ok("bundled data:text/html decodes (resolveEmbedHtml) + repairs to clean copy",
    repair(resolveEmbedHtml(dataUrl)) === "<p>press — then • go</p>");
})();

// ---- editor-chrome sanitiser: drag-handle + pasted-block chrome never persists ----
section("field-html sanitiser");
(function () {
  var etxt = src("src/editor.js");
  var body = etxt.slice(etxt.indexOf("var CHROME_SIG ="), etxt.indexOf("function sanitizeDeep(v)"));
  var clean = new Function(body + "\nreturn sanitizeFieldHtml;")();
  var Q = String.fromCharCode(38) + "quot;"; // &quot;
  // drag-handle overlay captured into innerHTML -> removed, text kept
  ok("removes the drag-handle div + gripper", clean('Course Nav<div class="canvas-drag-handle" draggable="true" contenteditable="false" title="Drag to reorder">⠿</div>') === "Course Nav");
  ok("removes a bare gripper char in plain text", clean("Heading⠿") === "Heading");
  // pasted canvas block: strip is-selected + selection outline (the frozen blue box)
  var pasted = '<ul class="body-list canvas-block is-editable is-selected" data-edit="text" data-rich="1" spellcheck="false" style="outline: 1.5px solid var(--ui-accent); caret-color: rgb(1,2,3); margin: 4px 0; font-size: 11px;" contenteditable="true"><li>x</li></ul>';
  var out = clean(pasted);
  ok("drops is-selected + editor classes, keeps render class", /class="body-list"/.test(out) && !/is-selected|canvas-block|is-editable/.test(out));
  ok("drops the --ui-accent selection outline (the blue box)", !/--ui-accent|outline/.test(out));
  ok("drops caret-color but keeps author styles", !/caret-color/.test(out) && /margin: 4px 0/.test(out) && /font-size: 11px/.test(out));
  ok("strips contenteditable/data-edit/data-rich/spellcheck attrs", !/contenteditable|data-edit|data-rich|spellcheck/.test(out));
  // must NOT corrupt an entity-bearing font-family (a &quot; ends in a semicolon)
  ok("preserves &quot; entities in style values", clean('<span style="caret-color: red; font-family: -apple-system, ' + Q + 'Segoe UI' + Q + ', Roboto;">t</span>').indexOf(Q + "Segoe UI" + Q) !== -1);
  // signature-gated: clean content + author interaction HTML untouched (idempotent)
  ok("no-op on clean text", clean("Just a heading") === "Just a heading");
  ok("leaves author HTML-interaction markup (no chrome signature) untouched", clean('<div class="widget" data-x="1" style="color:red">Hi</div>') === '<div class="widget" data-x="1" style="color:red">Hi</div>');
  ok("idempotent", clean(out) === out);
  // wired at BOTH the commit chokepoint and the on-load deep clean
  ok("writeModel runs it on commit", /writeModel\(node, value\)[\s\S]*?sanitizeText\(sanitizeFieldHtml\(value\)\)/.test(etxt));
  ok("sanitizeDeep heals existing docs on load", /if \(typeof v === "string"\) return sanitizeText\(sanitizeFieldHtml\(v\)\)/.test(etxt));
  // plain-text paste (§3 P1): editable fields strip a rich paste to text/plain so it
  // inherits the target's style — and never re-imports foreign chrome at the source.
  var pasteBody = etxt.slice(etxt.indexOf('addEventListener("paste"'), etxt.indexOf('// rich fields allow line breaks'));
  ok("editable fields bind a paste handler", pasteBody.length > 0);
  ok("paste prevents the default rich paste", /e\.preventDefault\(\)/.test(pasteBody));
  ok("paste reads text/plain only", /getData\("text\/plain"\)/.test(pasteBody));
  ok("paste sanitises then inserts as plain text", /__sanitizeText\(text\)[\s\S]*execCommand\("insertText", false, text\)/.test(pasteBody));
})();

// ---- WWW: applying a saved text style strips inline colour so the style colour WINS ----
section("WWW apply-style colour");
(function () {
  var etxt = src("src/editor.js");
  var body = etxt.slice(etxt.indexOf("function stripInlineColor("), etxt.indexOf("window.__stripInlineColor"));
  var strip = new Function(body + "\nreturn stripInlineColor;")();
  // the core symptom: a baked colour span survives font/size apply -> must be removed
  ok("strips inline color from a span (trailing ;)", strip('<span style="color: red;">x</span>') === '<span>x</span>');
  ok("removes color-only style attr entirely", strip('<span style="color:#ff0000">Hi</span>') === '<span>Hi</span>');
  ok("keeps other decls, drops only color (leading)", strip('<span style="color: red; font-size: 11px">t</span>') === '<span style="font-size: 11px">t</span>');
  ok("keeps other decls, drops only color (trailing)", strip('<b style="font-weight:700;color:#123">t</b>') === '<b style="font-weight:700">t</b>');
  // must NOT touch background-color (the (?:^|;) anchor guards it) — highlights survive
  ok("preserves background-color highlight", strip('<mark style="background-color: yellow">h</mark>') === '<mark style="background-color: yellow">h</mark>');
  ok("drops color but keeps background-color when both present", strip('<span style="background-color: yellow; color: red">h</span>') === '<span style="background-color: yellow">h</span>');
  // safe / pure
  ok("no-op when no colour present", strip("<p>plain paragraph</p>") === "<p>plain paragraph</p>");
  ok("non-string passes through", strip(42) === 42 && strip(null) === null);
  ok("idempotent", strip(strip('<span style="color: red; margin: 2px">t</span>')) === strip('<span style="color: red; margin: 2px">t</span>'));
  // wired into the apply-style handler (styleRef set -> strip the field HTML + push history)
  ok("apply-style handler strips the field HTML", /host\.styleRef = v;[\s\S]*?stripInlineColor\(obj\[field\]\)/.test(etxt));
  ok("apply-style pushes history (undoable)", /pushHistory\(\);\s*\n\s*host\.styleRef = v;/.test(etxt));
})();

// ---- §4 theme-aware saved-text-style colour: bind to a theme token (flips light/dark) ----
section("theme-aware style colour");
(function () {
  var rtxt = src("src/render.js");
  var body = rtxt.slice(rtxt.indexOf("function applyTextStyle("), rtxt.indexOf("window.applyTextStyle"));
  var applyTextStyle = new Function("FONT_STACKS", body + "\nreturn applyTextStyle;")({});
  var n1 = { style: {} }; applyTextStyle(n1, { colorToken: "ink" });
  ok("token -> var(--color-ink)", n1.style.color === "var(--color-ink)");
  var n2 = { style: {} }; applyTextStyle(n2, { colorToken: "ink-soft" });
  ok("kebab token preserved", n2.style.color === "var(--color-ink-soft)");
  var n3 = { style: {} }; applyTextStyle(n3, { color: "#ff0000" });
  ok("raw hex still applies when no token", n3.style.color === "#ff0000");
  var n4 = { style: {} }; applyTextStyle(n4, { colorToken: "accent", color: "#ff0000" });
  ok("token wins over hex when both on one style", n4.style.color === "var(--color-accent)");
  var n5 = { style: {} }; applyTextStyle(n5, {});
  ok("no colour -> empty (inherits theme)", n5.style.color === "");
  // MM: InDesign options — case (text-transform) + first-line indent
  var n6 = { style: {} }; applyTextStyle(n6, { textTransform: "uppercase", textIndent: 24 });
  ok("MM: case emits text-transform", n6.style.textTransform === "uppercase");
  ok("MM: indent emits text-indent px", n6.style.textIndent === "24px");
  var n7 = { style: {} }; applyTextStyle(n7, {});
  ok("MM: unset case/indent -> empty", n7.style.textTransform === "" && n7.style.textIndent === "");
  // Per-mode text colour (colorField Per-mode tab): applyTextStyle emits color:var(--tc-c)
  var nPM = { style: {} }; applyTextStyle(nPM, { colorLight: "#111111", colorDark: "#eeeeee" });
  ok("per-mode text colour → color:var(--tc-c)", nPM.style.color === "var(--tc-c)");
  ok("course.css switches --tc-c by data-mode", /\[style\*="--tc-light"\] \{ --tc-c: var\(--tc-light\); \}/.test(src("src/course.css")) && /\.course-root\[data-mode="dark"\] \[style\*="--tc-light"\] \{ --tc-c: var\(--tc-dark\); \}/.test(src("src/course.css")));
  // MM: justify (4th align) + word-spacing
  var n8 = { style: {} }; applyTextStyle(n8, { align: "justify", wordSpacing: 4 });
  ok("MM: justify emits text-align:justify", n8.style.textAlign === "justify");
  ok("MM: word-spacing emits px", n8.style.wordSpacing === "4px");
  ok("MM: unset word-spacing -> empty", n7.style.wordSpacing === "");
  ok("Edit-style dialog offers a Justify align option", /\[Icon\("align-right"\), "right", "Right"\], \[Icon\("align-justify"\), "justify", "Justify"\]/.test(src("src/editor.js")));
  ok("Edit-style dialog saves word-spacing", /if \(draft\.wordSpacing == null \|\| isNaN\(draft\.wordSpacing\)\) delete s\.wordSpacing; else s\.wordSpacing = draft\.wordSpacing/.test(src("src/editor.js")));
  // resolveBlockStyle: a per-block override of ONE colour form drops the named style's OTHER form
  ok("resolveBlockStyle: hex override drops the style's token", /if \(ov\.color != null && ov\.color !== ""\) delete merged\.colorToken/.test(rtxt));
  ok("resolveBlockStyle: token override drops the style's hex", /else if \(ov\.colorToken\) delete merged\.color/.test(rtxt));
  // editor dialog: token XOR hex on save + specimen resolves the var
  var etxt = src("src/editor.js");
  ok("Edit-style dialog saves colorToken (token clears hex)", /s\.colorToken = draft\.colorToken; delete s\.color/.test(etxt));
  ok("Edit-style dialog offers theme-token options", /COLOUR_TOKENS = \[\["Ink", "ink"\]/.test(etxt));
  ok("specimen seeds theme vars so a token resolves in preview", /applyTheme\(specimen, activeTheme\(\)\); window\.applyTextStyle\(specimen, draft\)/.test(etxt));
  ok("MM: Edit-style dialog exposes a Case control + Indent field", /segmentedLive\("Case"/.test(etxt) && /"First-line indent"/.test(etxt));
  ok("MM: Edit-style dialog saves textTransform + textIndent", /s\.textTransform = draft\.textTransform;[\s\S]*?s\.textIndent = draft\.textIndent/.test(etxt));
  // body paragraphs default to full ink (matching .body-list), not ink-soft — else a
  // colourless text style leaves paragraphs a shade lighter than lists (James's mismatch).
  var ccss = src("src/course.css");
  var bcStart = ccss.indexOf(".body-copy {");
  var bodyCopy = ccss.slice(bcStart, ccss.indexOf("}", bcStart));
  ok(".body-copy default colour is --color-ink (not ink-soft)", /color:\s*var\(--color-ink\)\s*;/.test(bodyCopy) && !/color:\s*var\(--color-ink-soft\)\s*;/.test(bodyCopy));
})();

// ---- WWW retroactive: existing styleRef blocks get inline colour stripped on load ----
section("WWW retroactive auto-clean");
(function () {
  var etxt = src("src/editor.js");
  var body = etxt.slice(etxt.indexOf("function stripInlineColor("), etxt.indexOf("function normalizeDoc("));
  var strip = new Function("window", body + "\nreturn stripStyledColorsDeep;")({});
  var block = { type: "text", styleRef: "Heading", text: '<p><span style="color:red">Hi</span></p>' };
  strip(block);
  ok("strips colour from a styleRef block's field", block.text === "<p><span>Hi</span></p>");
  // "override always wins": strip even WITHOUT a styleRef (no in-app colour command ->
  // any inline colour is foreign paste residue). This is the white-note case James hit.
  var free = { type: "note", text: '<span style="color: rgb(255, 255, 255)">Hi</span>' };
  strip(free);
  ok("strips inline colour even with NO styleRef (the white-note bug)", free.text === "<span>Hi</span>");
  var nested = { pages: [{ blocks: [{ type: "columns", cols: [[{ type: "text", text: '<b style="color:#123">x</b>' }]] }] }] };
  strip(nested);
  ok("reaches nested blocks (no styleRef needed)", nested.pages[0].blocks[0].cols[0][0].text === "<b>x</b>");
  // embeds / interaction markup keep their colours: skip the html/svg/src fields + full docs
  var embed = { type: "htmlEmbed", html: '<!DOCTYPE html><html><body><span style="color:red">x</span></body></html>' };
  strip(embed);
  ok("preserves colour inside an embed html field", /color:red/.test(embed.html));
  var svg = { svg: '<svg><text style="color:red">x</text></svg>' };
  strip(svg);
  ok("skips the svg field", /color:red/.test(svg.svg));
  var fullDoc = { text: '<!DOCTYPE html><html><span style="color:red">x</span></html>' };
  strip(fullDoc);
  ok("skips a full-HTML-document string even in a text field", /color:red/.test(fullDoc.text));
  var keep = { styleRef: "Heading", text: "plain" };
  strip(keep);
  ok("plain non-HTML strings untouched", keep.text === "plain" && keep.styleRef === "Heading");
  var b2 = { text: '<i style="color:red">y</i>' }; strip(b2); var once = b2.text; strip(b2);
  ok("idempotent", b2.text === once && once === "<i>y</i>");
  ok("normalizeDoc runs the retroactive clean", /stripStyledColorsDeep\(d\);/.test(etxt));
})();

// ---- §10b shared component library slice 2: "Blocks" palette insert ----
// (moved from the Blocks palette's "Shared Library" asset-group into the dedicated
// Components left-pane twirl's "Blocks" group as part of the left-panel reorg)
section("shared-library palette insert");
(function () {
  var etxt = src("src/editor.js");
  var reg = etxt.indexOf("SHARED component library (cross-course");
  ok("renderComponentsPalette adds a Blocks palette section", reg > -1);
  var body = etxt.slice(reg, reg + 1400);
  ok("sources it from the cross-course libComponents(), not doc components", /var lib = libComponents\(\)/.test(body));
  ok("only surfaces composed defs (slot-def render fns aren't serialisable)", /kind === "composed" && lib\[k\]\.template/.test(body));
  ok("titles the section \"Blocks\"", /renderGroup\("Blocks"/.test(body));
  // #20: insert now places a LIVE-LINKED libraryInstance wrapper, not a detached copy
  // (a deliberate behavior change from the original slice-2 copy-insert -- "My Components"
  // below/elsewhere keeps copy-insert, this only applies to the cross-course shared library).
  ok("insert places a live-linked libraryInstance wrapper (not a copy)", /insertBlock\(\{ type: "libraryInstance", id: mintId\(\), ref: k \}\)/.test(body));
  var groupFn = etxt.slice(etxt.indexOf("function renderGroup(title, rows, emptyHint)"), etxt.indexOf("function renderGroup(title, rows, emptyHint)") + 500);
  ok("collapse state persists like other palette groups", /setGroupCollapsed\(title, !det\.open\)/.test(groupFn));
})();

// ---- #20: library-instance mirror (live-linked, promote ANY composed block) -----
section("#20 library-instance mirror");
(function () {
  var etxt = src("src/editor.js");
  var rtxt = src("src/render.js");

  // 1. render.js resolves the CURRENT master live (doc override -> library -> built-in),
  // same order as componentGrid's resolveComponentDef -- single-source, bakes at export.
  var libStart = rtxt.indexOf("libraryInstance: function (block)");
  ok("render.js defines BLOCKS.libraryInstance", libStart !== -1);
  var libBody = rtxt.slice(libStart, libStart + 1700);
  ok("resolves doc override -> shared library -> built-in", /docComps && docComps\[block\.ref\]\) \|\| libComps\[block\.ref\] \|\| \(window\.COMPONENTS \|\| \{\}\)\[block\.ref\]/.test(libBody));
  ok("renders a cloneData() COPY of the master, never the live object (editor-safety)", /var content = cloneData\(facetTemplate\);[\s\S]{0,600}var node = renderBlock\(content\)/.test(libBody));
  ok("applies #21 overrides onto the CLONE, not the live master", /if \(block\.overrides\) applyInstanceOverrides\(content, block\.overrides\)/.test(libBody));
  ok("marks the wrapper node for the editor-only opacity rule", /data-library-instance/.test(libBody));

  // 2. editor.js: selection routing, contentless inspector, tree label/icon, all mirror
  // componentGrid's existing precedent for a def-resolving block type.
  ok("TWO_LEVEL_TYPES includes libraryInstance (contentless like componentGrid)", /TWO_LEVEL_TYPES = \{[^}]*libraryInstance: 1/.test(etxt));
  ok("getSelectionTypeForBlock routes libraryInstance to 'block'", /if \(block\.type === "componentGrid"\) return "block";\s*\n\s*if \(block\.type === "libraryInstance"\) return "block";/.test(etxt));
  ok("inspector dispatch reuses renderContentlessBlock", /if \(block\.type === "libraryInstance"\) \{ renderContentlessBlock\(node, "Library instance", renderLibraryInstanceBody\); return; \}/.test(etxt));
  ok("block-icon map has a libraryInstance glyph", /libraryInstance: "component"/.test(etxt));
  ok("tree label resolves the master's name via resolveComponentDef", /if \(b\.type === "libraryInstance"\) \{ var libDef = resolveComponentDef\(b\.ref\)/.test(etxt));

  // 3. the inspector body reuses componentGrid card's OWN "instance" header language
  // (prop-component--instance), and offers Detach as the only structural action in v1.
  var lbStart = etxt.indexOf("function renderLibraryInstanceBody(node)");
  ok("renderLibraryInstanceBody found", lbStart !== -1);
  var lbBody = etxt.slice(lbStart, lbStart + 5000);
  ok("reuses the canonical instance header (same class componentGrid cards use)", /"prop-component prop-component--instance"/.test(lbBody));
  ok("offers a Detach action, disabled when the master is missing", /detachB\.disabled = !def/.test(lbBody));

  // 4. Detach: #19 says preserve on promote/copy but REMINT on a genuine new landed
  // copy -- a detach IS that case, so (unlike Copy-to-course/Save-to-library) it MUST
  // call remintIds, or every detached instance of the same master would collide.
  var daStart = etxt.indexOf("function detachLibraryInstance(block)");
  ok("detachLibraryInstance found", daStart !== -1);
  var daBody = etxt.slice(daStart, daStart + 1600);
  ok("detach mints a FRESH remint of the master's current (override-baked) template", /var fresh = remintIds\(withOverrides\)/.test(daBody));
  ok("detach bakes in the author's overrides, not the master's raw content", /if \(block\.overrides && window\.applyInstanceOverrides\) window\.applyInstanceOverrides\(withOverrides, block\.overrides\)/.test(daBody));
  ok("detach replaces the wrapper's fields in place (stays the same page-tree node)", /Object\.keys\(block\)\.forEach\(function \(k\) \{ delete block\[k\]; \}\)/.test(daBody));

  // 5. editor.css scopes the "opaque instance" rule to the marker attribute, and never
  // applies to course.css/render output (editor-only chrome, per the pure-render invariant).
  var css = src("editor.css");
  ok("editor.css disables pointer-events on nested canvas-blocks inside a library instance", /\[data-library-instance\] \.canvas-block \{ pointer-events: none; \}/.test(css));
  ok("course.css does not reference the library-instance marker (editor-chrome only)", src("src/course.css").indexOf("data-library-instance") === -1);
})();

// ---- Product Rail: tag vocabulary + reserved owning-Product tag --------------
section("product-rail tag vocabulary");
(function () {
  var etxt = src("src/editor.js");

  // 1. PURE: the tag-vocab fence, extracted headlessly.
  var tStart = etxt.indexOf("/* @tag-vocab-start */");
  var tEnd = etxt.indexOf("/* @tag-vocab-end */");
  var mod = new Function(etxt.slice(tStart, tEnd) +
    "\nreturn { ownerProductTagValue: ownerProductTagValue, stampOwnerProductTag: stampOwnerProductTag," +
    " addTechnologyTag: addTechnologyTag, removeMasterTag: removeMasterTag, matchTagVocabulary: matchTagVocabulary };")();
  ok("tag-vocab functions extracted", typeof mod.stampOwnerProductTag === "function");

  // stampOwnerProductTag: stamped once, from a Product context; absent when there is none.
  var m1 = { name: "Topic" };
  mod.stampOwnerProductTag(m1, "prod-a");
  ok("stamps a reserved tag from the given productId", m1.tags.length === 1 && m1.tags[0].value === "product:prod-a" && m1.tags[0].reserved === true);
  mod.stampOwnerProductTag(m1, "prod-b");
  ok("never re-stamps once a reserved tag already exists", m1.tags.filter(function (t) { return t.reserved; }).length === 1 && m1.tags[0].value === "product:prod-a");
  var m2 = {};
  mod.stampOwnerProductTag(m2, null);
  ok("no Product context -> tags initialised but no reserved tag (nothing to attribute)", Array.isArray(m2.tags) && m2.tags.length === 0);
  ok("stampOwnerProductTag is null-safe", mod.stampOwnerProductTag(null, "prod-a") === null);

  // addTechnologyTag / removeMasterTag: freeform, no dupes, reserved tag is protected.
  var m3 = { tags: [{ value: "product:prod-a", reserved: true }] };
  mod.addTechnologyTag(m3, "radar");
  mod.addTechnologyTag(m3, "radar"); // duplicate, ignored
  ok("adds a freeform technology tag, de-duped", m3.tags.length === 2 && m3.tags.filter(function (t) { return t.value === "radar"; }).length === 1);
  mod.removeMasterTag(m3, "product:prod-a");
  ok("ordinary tag-editing CANNOT remove the reserved tag", m3.tags.some(function (t) { return t.reserved; }));
  mod.removeMasterTag(m3, "radar");
  ok("a freeform tag CAN be removed", !m3.tags.some(function (t) { return t.value === "radar"; }));

  // matchTagVocabulary: autocomplete-first, "propose new" only on a genuine non-match.
  var vocab = ["radar", "radar-jamming", "acoustic"];
  ok("empty query -> no matches, not exact (nothing to propose either)", mod.matchTagVocabulary(vocab, "").matches.length === 0 && mod.matchTagVocabulary(vocab, "").exact === false);
  ok("a substring query surfaces autocomplete matches", mod.matchTagVocabulary(vocab, "radar").matches.length === 2);
  ok("an exact existing tag is flagged exact (never proposed as new)", mod.matchTagVocabulary(vocab, "acoustic").exact === true);
  ok("a genuine non-match has no matches and is not exact -> caller falls back to propose-new", mod.matchTagVocabulary(vocab, "thermal").matches.length === 0 && mod.matchTagVocabulary(vocab, "thermal").exact === false);

  // 2. editor.js wiring: promotion to the shared library stamps the reserved tag from
  // THIS course's Product context (doc.meta.productId), exactly once, at promotion time.
  var doSaveIdx = etxt.indexOf("function doSave() {\n          pushHistory();\n          // #19: plain clone()");
  ok("promote-to-library doSave() found", doSaveIdx !== -1);
  var doSaveBody = etxt.slice(doSaveIdx, doSaveIdx + 1200);
  ok("stamps the reserved owning-Product tag from doc.meta.productId at promotion time", /stampOwnerProductTag\(promoted, doc\.meta && doc\.meta\.productId\)/.test(doSaveBody));
  var stampIdx = doSaveBody.indexOf("stampOwnerProductTag(promoted");
  var storeIdx = doSaveBody.indexOf("window.LibraryStore.components[selectedKey] = promoted;");
  ok("stamping happens BEFORE the master lands in the shared store", stampIdx !== -1 && storeIdx !== -1 && stampIdx < storeIdx);
})();

// ---- #21: instance local overrides + structure reconciliation + detach/relink ----
section("#21 instance overrides + reconciliation + relink");
(function () {
  var etxt = src("src/editor.js");
  var rtxt = src("src/render.js");

  // 1. PURE: reconcileOverrides / collectOverridableTextFields, extracted headlessly.
  var pStart = etxt.indexOf("var TEXT_STYLE_TYPES = {");
  var pEnd = etxt.indexOf("/* @overrides-end */");
  var pureBody = etxt.slice(pStart, pEnd);
  var mod = new Function(pureBody + "\nreturn { collectOverridableTextFields: collectOverridableTextFields, reconcileOverrides: reconcileOverrides };")();
  ok("pure functions extracted", typeof mod.reconcileOverrides === "function" && typeof mod.collectOverridableTextFields === "function");

  var master = { id: "b_ROOT", type: "frame", children: [
    { id: "b_H", type: "heading", text: "Title" },
    { id: "b_P", type: "paragraph", text: "Body" },
    { id: "b_IMG", type: "image", src: "asset:x" } // not text-bearing -- must be excluded
  ] };
  var fields = mod.collectOverridableTextFields(master);
  ok("collects only text-bearing fields (heading+paragraph, not image)", fields.length === 2 && fields.map(function (f) { return f.id; }).sort().join(",") === "b_H,b_P");
  ok("captures the master's CURRENT text as context", fields.filter(function (f) { return f.id === "b_H"; })[0].text === "Title");

  var rec1 = mod.reconcileOverrides(master, { b_H: { text: "Override" }, b_P: { text: "Also" } });
  ok("reconcile: all-surviving overrides are all living, none dropped", Object.keys(rec1.living).length === 2 && rec1.dropped.length === 0);

  var rec2 = mod.reconcileOverrides(master, { b_H: { text: "Override" }, b_GONE: { text: "Stale" } });
  ok("reconcile: a field removed from the master -> that override is DROPPED", rec2.dropped.length === 1 && rec2.dropped[0] === "b_GONE");
  ok("reconcile: a still-existing field's override is KEPT (living)", rec2.living.b_H && rec2.living.b_H.text === "Override" && !rec2.living.b_GONE);

  // Reorder must never drop anything -- overrides key to a stable id, not a position.
  var reordered = { id: "b_ROOT", type: "frame", children: [master.children[2], master.children[1], master.children[0]] };
  var rec3 = mod.reconcileOverrides(reordered, { b_H: { text: "Override" }, b_P: { text: "Also" } });
  ok("reconcile: reordering the master's children drops nothing", rec3.dropped.length === 0 && Object.keys(rec3.living).length === 2);

  // 2. render.js: applyInstanceOverrides walks the SAME shape reconcile/collect do, and
  // is applied to the CLONE (never the live master) before render.
  var aoStart = rtxt.indexOf("function applyInstanceOverrides(node, overrides)");
  ok("render.js defines applyInstanceOverrides", aoStart !== -1);
  var aoBody = rtxt.slice(aoStart, aoStart + 900);
  ["node.children.forEach", "node.columns.forEach", "node.items.forEach", "node.screens.forEach"].forEach(function (needle) {
    ok("applyInstanceOverrides descends " + needle.split(".")[1], aoBody.indexOf(needle) !== -1);
  });

  // 3. editor.js wiring: renderLibraryInstanceBody reconciles-on-open (prunes + persists +
  // surfaces a drop), then lists override fields via the canonical fieldRow control.
  var lbStart = etxt.indexOf("function renderLibraryInstanceBody(node)");
  var lbBody2 = etxt.slice(lbStart, lbStart + 4000);
  ok("reconciles on open via reconcileOverrides(def.template, ...)", /var rec = reconcileOverrides\(def\.template, block\.overrides \|\| \{\}\)/.test(lbBody2));
  ok("prunes the block's overrides to the living set", /block\.overrides = rec\.living/.test(lbBody2));
  ok("surfaces a drop with the warn hint class", /insp-hint insp-hint--warn/.test(lbBody2));
  ok("lists override fields via the canonical fieldRow control", /fields\.forEach\(function \(f\) \{[\s\S]{0,150}fieldRow\(/.test(lbBody2));
  ok("an empty override reverts to inherit (delete, not empty-string store)", /if \(v\) block\.overrides\[f\.id\] = \{ text: v \}; else delete block\.overrides\[f\.id\]/.test(lbBody2));
  // #163 gate: must NOT reintroduce a raw sub() section header for the new Overrides group.
  ok("Overrides label uses the stacked-label pattern, not a new sub() header", /"insp-row__label insp-row__label--stacked", "Overrides"/.test(lbBody2) && lbBody2.indexOf('sub("Overrides")') === -1);

  // 4. Detach discards overrides (they were keyed to the mirror) and leaves a __linkedFrom
  // breadcrumb; Relink is gated on it and gives a lossy-edit warning before acting.
  var daStart2 = etxt.indexOf("function detachLibraryInstance(block)");
  var daBody2 = etxt.slice(daStart2, daStart2 + 1600);
  ok("detach records __linkedFrom for a future relink", /block\.__linkedFrom = ref/.test(daBody2));

  var rlStart = etxt.indexOf("function relinkToLibrary(block, ref)");
  ok("relinkToLibrary found", rlStart !== -1);
  var rlBody = etxt.slice(rlStart, rlStart + 400);
  ok("relink rebuilds a fresh libraryInstance wrapper (fresh id, same ref)", /block\.type = "libraryInstance";[\s\S]{0,60}block\.id = mintId\(\);[\s\S]{0,60}block\.ref = ref;/.test(rlBody));

  var frStart = etxt.indexOf("function renderFrameOrGroupTwoLevel(node)");
  var frBody = etxt.slice(frStart, frStart + 3200);
  ok("Relink button is gated on __linkedFrom (never shown on an ordinary frame)", /if \(block\.__linkedFrom\) \{/.test(frBody));
  ok("Relink warns that local edits since detach are discarded", /discarded/.test(frBody));
})();

// ---- #24: where-used + impact preview + push-update ------------------------
section("#24 where-used + impact preview + push-update");
(function () {
  var etxt = src("src/editor.js");

  // 1. PURE: libraryWhereUsed against a fixture multi-course registry. Extracted as TWO
  // pieces (walkBlocks, then the @where-used fence) so the concatenation skips the
  // @comment-guest fence's own window.__commentModel line sitting between them.
  var wbStart = etxt.indexOf("function walkBlocks(doc, visit)");
  var wbEnd = etxt.indexOf("function docCids(doc, acc)");
  var wuStart = etxt.indexOf("/* @where-used-start */");
  var wuEnd = etxt.indexOf("/* @where-used-end */");
  var pureBody = etxt.slice(wbStart, wbEnd) + etxt.slice(wuStart, wuEnd);
  var mod = new Function(pureBody + "\nreturn { libraryWhereUsed: libraryWhereUsed, libraryWhereUsedDetail: libraryWhereUsedDetail };")();
  ok("libraryWhereUsed extracted", typeof mod.libraryWhereUsed === "function");
  ok("libraryWhereUsedDetail extracted", typeof mod.libraryWhereUsedDetail === "function");

  function mkCourse(refs) {
    return { pages: [{ blocks: refs.map(function (ref) { return { type: "libraryInstance", ref: ref }; }) }] };
  }
  var registry = {
    "C-1": mkCourse(["comp-a", "comp-a", "comp-b"]), // 2 instances of comp-a, 1 of comp-b
    "C-2": mkCourse(["comp-a"]),                     // 1 more instance of comp-a, different course
    "C-3": mkCourse([])                              // no instances at all
  };
  var wu = mod.libraryWhereUsed("comp-a", registry);
  ok("counts courses correctly (comp-a used in C-1 + C-2)", wu.courses === 2);
  ok("counts instances correctly (2 in C-1 + 1 in C-2)", wu.instances === 3);
  var wuNone = mod.libraryWhereUsed("comp-nowhere", registry);
  ok("a ref used nowhere -> 0/0", wuNone.courses === 0 && wuNone.instances === 0);
  // nested placement (inside a frame's children) must still be found -- walkBlocks descends.
  var nested = { "C-4": { pages: [{ blocks: [{ type: "frame", children: [{ type: "libraryInstance", ref: "comp-c" }] }] }] } };
  ok("finds a nested libraryInstance (inside a frame's children)", mod.libraryWhereUsed("comp-c", nested).instances === 1);

  // Product Rail (source-stage-info-panel): libraryWhereUsedDetail is the per-usage
  // sibling -- one entry per referencing block, carrying the document title + block
  // id (so a caller can label AND jump to each usage), not just aggregate counts.
  var registryTitled = {
    "C-1": { meta: { title: "Course One" }, pages: [{ blocks: [{ type: "libraryInstance", ref: "topic-x", id: "b_1" }] }] },
    "C-2": { meta: { title: "Course Two" }, pages: [{ blocks: [{ type: "libraryInstance", ref: "topic-x", id: "b_2" }, { type: "libraryInstance", ref: "topic-x", id: "b_3" }] }] },
    "C-3": { pages: [{ blocks: [] }] } // no reference at all
  };
  var detail = mod.libraryWhereUsedDetail("topic-x", registryTitled);
  ok("libraryWhereUsedDetail returns one entry per referencing block (3 total)", detail.length === 3);
  ok("each entry carries docCode + docTitle + blockId", detail[0].docCode === "C-1" && detail[0].docTitle === "Course One" && detail[0].blockId === "b_1");
  ok("a doc with no meta.title falls back to its code", mod.libraryWhereUsedDetail("comp-nowhere", { "C-9": { meta: {}, pages: [{ blocks: [{ type: "libraryInstance", ref: "comp-nowhere", id: "b_9" }] }] } })[0].docTitle === "C-9");
  ok("a ref used nowhere -> empty list, never throws", mod.libraryWhereUsedDetail("nothing-here", registryTitled).length === 0);

  // 2. WIRING: the Component Library panel shows the where-used count per master.
  var lStart = etxt.indexOf("function buildLibraryBody(c)");
  var lBody = etxt.slice(lStart, lStart + 11200);
  ok("buildLibraryBody computes where-used per master via the registry", /var usage = libraryWhereUsed\(k, getRegistry\(\)\)/.test(lBody));
  ok("shows a 'Used in N course(s) / M instance(s)' meta line", /"Used in " \+ usage\.courses/.test(lBody));
  ok("shows 'Not placed anywhere yet' when usage is zero", /Not placed anywhere yet/.test(lBody));

  // 3. WIRING: Push update — confirms + durably saves, does NOT claim to mutate other
  // courses' stored data (architecturally, #20 live instances need no push to be current).
  ok("Push update button present", /h\("button", "prop-btn", "Push update"\)/.test(lBody));
  ok("Push update calls saveLibrary() (durable save) before reporting", /pushB\.addEventListener\("click", function \(\) \{\s*\n\s*saveLibrary\(\);/.test(lBody));
  ok("Push update reports the FRESH where-used count as the result", /var fresh = libraryWhereUsed\(k, getRegistry\(\)\)/.test(lBody));

  // 4. WIRING: impact preview on the two places a master's blast radius actually matters
  // — overwriting it (the one place its content changes) and removing it.
  ok("'Save to library' overwrite confirm shows an impact preview", /libraryWhereUsed\(selectedKey, getRegistry\(\)\)[\s\S]{0,400}confirmModal\("Overwrite component"/.test(lBody));
  ok("'Remove' confirm shows the current usage before a destructive action", /var impact = libraryWhereUsed\(k, getRegistry\(\)\)[\s\S]{0,400}confirmModal\("Remove component"/.test(lBody));
})();

// ---- #23: axis-owning library masters (variant + software-version inheritance) ----
section("#23 axis-owning library masters");
(function () {
  var rtxt = src("src/render.js");
  var etxt = src("src/editor.js");
  var extxt = src("src/export.js");

  // 1. PURE: resolveLibraryAxisContent, extracted with the whole axis engine it depends on.
  var axStart = rtxt.indexOf("var VARIANT_AXIS = {");
  var axEnd = rtxt.indexOf("window.resolveLibraryAxisContent = resolveLibraryAxisContent;");
  var axBody = rtxt.slice(axStart, axEnd);
  var mod = new Function(axBody + "\nreturn { resolveLibraryAxisContent: resolveLibraryAxisContent };")();
  ok("resolveLibraryAxisContent extracted", typeof mod.resolveLibraryAxisContent === "function");

  var master = {
    id: "b_ROOT", type: "frame", children: [
      { id: "b_H", type: "heading", text: "Base text", overrides: { pro: { text: "Pro text" } }, versionOverrides: { v2: { text: "V2 text" } } }
    ]
  };
  ok("no axis context -> unresolved (base/raw content)", mod.resolveLibraryAxisContent(master, {}).children[0].text === "Base text");
  ok("variant context resolves the variant override", mod.resolveLibraryAxisContent(master, { variant: "pro" }).children[0].text === "Pro text");
  ok("a variant with no override for this node falls through to base (no crash)", mod.resolveLibraryAxisContent(master, { variant: "lite" }).children[0].text === "Base text");
  ok("version context resolves the version override", mod.resolveLibraryAxisContent(master, { version: "v2" }).children[0].text === "V2 text");
  ok("BOTH axes compose (variant then version, independent namespaces)", mod.resolveLibraryAxisContent(master, { variant: "pro", version: "v2" }).children[0].text === "V2 text");
  // visibility: a node tagged only:["pro"] must be dropped from a NON-pro variant's children.
  var withVis = { id: "b_ROOT2", type: "frame", children: [{ id: "b_only", type: "paragraph", text: "only pro", variantVis: { only: ["pro"] } }] };
  ok("variantVis only:[...] hides the node for a non-matching variant", mod.resolveLibraryAxisContent(withVis, { variant: "lite" }).children.length === 0);
  ok("variantVis only:[...] keeps the node for a matching variant", mod.resolveLibraryAxisContent(withVis, { variant: "pro" }).children.length === 1);

  // 2. render.js wiring: BLOCKS.libraryInstance resolves axis content BEFORE instance
  // overrides (axis first, instance override wins on top -- the agreed precedence).
  var libStart = rtxt.indexOf("libraryInstance: function (block)");
  var libBody2 = rtxt.slice(libStart, libStart + 1300);
  ok("axis-resolves via the per-pass hook before applying instance overrides", /content = resolveLibraryAxisContent\(content, window\.__libraryAxisContext\);[\s\S]{0,150}if \(block\.overrides\) applyInstanceOverrides\(content, block\.overrides\)/.test(libBody2));

  // 3. editor.js wiring: currentDoc() keeps the hook in sync (variant never null --
  // falls back to hero/identity; version null when the doc has no version axis).
  var cdStart = etxt.indexOf("function currentDoc()");
  var cdBody = etxt.slice(cdStart, cdStart + 1200);
  ok("currentDoc sets window.__libraryAxisContext", /window\.__libraryAxisContext = \{/.test(cdBody));
  ok("variant falls back to hero/identity, never null", /variant: activeVariant \|\| \(d\.heroVariant \|\| "hero"\)/.test(cdBody));
  ok("version falls back to the doc's base version, or null if none", /version: activeVersion \|\| \(d\.versions && d\.versions\[0\]\) \|\| null/.test(cdBody));

  // 4. editor.js wiring: detach bakes axis content (same principle as #21's override bake),
  // BEFORE instance overrides -- same precedence as render.js.
  var daStart = etxt.indexOf("function detachLibraryInstance(block)");
  var daBody = etxt.slice(daStart, daStart + 1600);
  ok("detach bakes axis content via resolveLibraryAxisContent", /withOverrides = window\.resolveLibraryAxisContent\(withOverrides, window\.__libraryAxisContext\)/.test(daBody));
  var axisIdx = daBody.indexOf("resolveLibraryAxisContent(withOverrides");
  var ovIdx = daBody.indexOf("applyInstanceOverrides(withOverrides");
  ok("detach resolves axis content BEFORE instance overrides (same precedence as render)", axisIdx !== -1 && ovIdx !== -1 && axisIdx < ovIdx);

  // 5. export.js wiring: both build paths (variant N-packages, per-version bake-into-one)
  // keep the hook in sync with the EFFECTIVE key being built for.
  ok("buildPackage sets the variant half of the hook (never null)", /window\.__libraryAxisContext = \{ variant: opts\.variant \|\| \(baseDoc\.heroVariant \|\| "hero"\), version: null \}/.test(extxt));
  ok("serializeVersionedPages sets version per-pass in the multi-version loop", /if \(window\.__libraryAxisContext\) window\.__libraryAxisContext\.version = v; \/\/ #23/.test(extxt));
  ok("serializeVersionedPages sets version on the no-wrapper (<2 versions) path too", /if \(window\.__libraryAxisContext\) window\.__libraryAxisContext\.version = \(versions && versions\[0\]\) \|\| null;/.test(extxt));
})();

// ---- Product Rail: facet pointer + {topic×variant×facet} schema --------------
section("product-rail facet pointer schema");
(function () {
  var rtxt = src("src/render.js");
  var etxt = src("src/editor.js");

  // 1. PURE: resolveFacetTemplate.
  var fStart = rtxt.indexOf("function resolveFacetTemplate(def, facetPointer)");
  var fEnd = rtxt.indexOf("window.resolveFacetTemplate = resolveFacetTemplate;");
  var fBody = rtxt.slice(fStart, fEnd);
  var mod = new Function(fBody + "\nreturn { resolveFacetTemplate: resolveFacetTemplate };")();
  ok("resolveFacetTemplate extracted", typeof mod.resolveFacetTemplate === "function");

  var master = {
    template: { id: "root", type: "frame", children: [{ id: "t", type: "heading", text: "Base" }] },
    facets: {
      technical: { name: "Technical", template: { id: "root-t", type: "frame", children: [{ id: "tt", type: "heading", text: "Technical detail" }] } },
      dotpoint: { name: "Dot-point", template: { id: "root-d", type: "frame", children: [{ id: "dd", type: "heading", text: "Dot points" }] } }
    }
  };
  ok("no pointer -> falls back to def.template", mod.resolveFacetTemplate(master, undefined).children[0].text === "Base");
  ok("a matching pointer resolves that facet's own template", mod.resolveFacetTemplate(master, "technical").children[0].text === "Technical detail");
  ok("a different pointer resolves a DIFFERENT facet", mod.resolveFacetTemplate(master, "dotpoint").children[0].text === "Dot points");
  ok("an unknown pointer falls back to def.template (no crash)", mod.resolveFacetTemplate(master, "no-such-facet").children[0].text === "Base");
  var plain = { template: { id: "root2", type: "frame", children: [] } };
  ok("a master with no facets at all behaves exactly as before", mod.resolveFacetTemplate(plain, "technical") === plain.template);
  ok("null def -> null (no crash)", mod.resolveFacetTemplate(null, "technical") === null);

  // Purity: resolving never mutates the master (it's a pure function of (topic, pointer)).
  var before = JSON.stringify(master);
  mod.resolveFacetTemplate(master, "technical");
  ok("resolving a facet never mutates the master", JSON.stringify(master) === before);

  // docTypeRenderings is a structurally distinct field from facets -- the resolver only
  // ever reads def.facets, so a doc-type rendering is never reachable via a facet pointer.
  var visualMaster = { template: { id: "vroot", type: "frame", children: [] }, docTypeRenderings: { interactive: { template: { id: "vi", type: "frame", children: [{ id: "vit", type: "heading", text: "Interactive" }] } } } };
  ok("docTypeRenderings is never read by the facet resolver (structurally distinct)", mod.resolveFacetTemplate(visualMaster, "interactive") === visualMaster.template);

  // 2. render.js wiring: BLOCKS.libraryInstance resolves the facet pointer before cloning.
  var libStart = rtxt.indexOf("libraryInstance: function (block)");
  var libBody = rtxt.slice(libStart, libStart + 900);
  ok("libraryInstance resolves block.facet via resolveFacetTemplate before cloning", /var facetTemplate = resolveFacetTemplate\(def, block\.facet\);[\s\S]{0,200}var content = cloneData\(facetTemplate\);/.test(libBody));

  // 3. editor.js wiring: detach bakes the resolved facet (not unconditionally def.template),
  // and drops the pointer along with every other own key -- no live pointer survives a fork.
  var daStart = etxt.indexOf("function detachLibraryInstance(block)");
  var daBody = etxt.slice(daStart, daStart + 1600);
  ok("detach resolves the facet actually showing before baking", /var facetTemplate = window\.resolveFacetTemplate \? window\.resolveFacetTemplate\(def, block\.facet\) : \(def && def\.template\);/.test(daBody));
  ok("detach clones the RESOLVED facet template", /var withOverrides = clone\(facetTemplate\);/.test(daBody));
  ok("detach drops block.facet along with every other own key (no live pointer survives a fork)", /Object\.keys\(block\)\.forEach\(function \(k\) \{ delete block\[k\]; \}\);/.test(daBody));

  // 4. editor.js wiring: the facet switcher only ever reads def.facets, never
  // def.docTypeRenderings -- so a doc-type rendering can never appear as an author picker.
  ok("facet picker is gated on def.facets", etxt.indexOf('if (def && def.facets && typeof def.facets === "object")') !== -1);
  ok("no picker anywhere reads def.docTypeRenderings (structurally distinct, export-time only)", etxt.indexOf("def.docTypeRenderings") === -1);
  ok("switching the facet select applies immediately (dsSelect onChange), no confirmModal", /var fSel = dsSelect\(facetOpts, curFacet, function \(v\) \{[\s\S]{0,150}if \(v\) block\.facet = v; else delete block\.facet;/.test(etxt));
})();

// ---- #22: section + page library masters ------------------------------------
section("#22 section + page library masters");
(function () {
  var rtxt = src("src/render.js");
  var etxt = src("src/editor.js");
  var css = src("editor.css");

  // 1. SECTION masters: groupMulti + saveBlockAsComponent, reused verbatim.
  ok("groupMulti returns the resulting group block", /return frame; \/\/ #22/.test(etxt));
  var ssStart = etxt.indexOf("function saveSelectionAsSectionMaster()");
  ok("saveSelectionAsSectionMaster found", ssStart !== -1);
  var ssBody = etxt.slice(ssStart, ssStart + 200);
  ok("reuses groupMulti + saveBlockAsComponent, no new capture logic", /var frame = groupMulti\(\);[\s\S]{0,40}if \(frame\) saveBlockAsComponent\(frame\)/.test(ssBody));
  ok("'Save selection to library…' wired into the outliner context menu", /label: "Save selection to library…", onClick: function \(\) \{ saveSelectionAsSectionMaster\(\); \}/.test(etxt));
  var multiMenuCount = (etxt.match(/label: "Save selection to library…"/g) || []).length;
  ok("wired into BOTH multi-select context menus (outliner + canvas)", multiMenuCount === 2);

  // 2. render.js: page masters resolve live, same shape as #20's block resolve.
  var rpStart = rtxt.indexOf("function resolvePageLibraryContent(page)");
  ok("resolvePageLibraryContent found", rpStart !== -1);
  var rpBody = rtxt.slice(rpStart, rpStart + 800);
  ok("resolves doc override -> shared library (page kind)", /docComps && docComps\[page\.libraryRef\]\) \|\| libComps\[page\.libraryRef\]/.test(rpBody));
  ok("resolves axis content THEN instance overrides per block (same precedence as #23)", /content = resolveLibraryAxisContent\(content, window\.__libraryAxisContext\);[\s\S]{0,80}if \(page\.overrides\) applyInstanceOverrides\(content, page\.overrides\)/.test(rpBody));
  var bpStart = rtxt.indexOf("function buildPageSection(page)");
  var bpBody = rtxt.slice(bpStart, bpStart + 1600);
  ok("buildPageSection marks a page instance for the editor-only opacity rule", /data-library-page-instance/.test(bpBody));
  ok("a missing master renders an empty (not broken) page", /if \(!blocks\) blocks = \[\];/.test(bpBody));

  // 3. editor.js: capture / insert / detach / where-used, all mirroring the block-level
  // (#19/#20/#21/#24) conventions at page scope.
  var spStart = etxt.indexOf("function savePageAsLibraryMaster(pi)");
  var spBody = etxt.slice(spStart, spStart + 900);
  ok("savePageAsLibraryMaster found", spStart !== -1);
  ok("page capture mints every block's id ONCE (remintIds per block, #19's contract)", /var blocks = \(page\.blocks \|\| \[\]\)\.map\(function \(b\) \{ return remintIds\(clone\(b\)\); \}\)/.test(spBody));
  ok("saves kind:\"page\" directly to the shared library (no doc.components staging step)", /kind: "page", template: \{ blocks: blocks \}/.test(spBody));

  var ipStart = etxt.indexOf("function insertPageFromLibrary(key)");
  ok("insertPageFromLibrary found", ipStart !== -1);
  var ipBody = etxt.slice(ipStart, ipStart + 700);
  ok("mints a fresh page id (never reused from the master)", /id: "page-" \+ Date\.now\(\) \+ "-" \+ Math\.random\(\)/.test(ipBody));
  ok("syncs courseNav section membership like duplicatePage does", /eachCourseNav\(function \(nav\)/.test(ipBody));

  var dpStart = etxt.indexOf("function detachPageLibraryInstance(pi)");
  var dpBody = etxt.slice(dpStart, dpStart + 900);
  ok("detachPageLibraryInstance found", dpStart !== -1);
  var dpAxisIdx = dpBody.indexOf("resolveLibraryAxisContent(withOverrides");
  var dpOvIdx = dpBody.indexOf("applyInstanceOverrides(withOverrides");
  var dpRemintIdx = dpBody.indexOf("return remintIds(withOverrides)");
  ok("detach resolves axis, THEN overrides, THEN remints -- same order as blocks (#21/#23)", dpAxisIdx !== -1 && dpOvIdx !== -1 && dpRemintIdx !== -1 && dpAxisIdx < dpOvIdx && dpOvIdx < dpRemintIdx);
  ok("detach leaves a __linkedFrom breadcrumb (no page-level Relink in this ticket's scope)", /page\.__linkedFrom = ref/.test(dpBody));

  ok("libraryWhereUsed also counts PAGE instances, not just libraryInstance blocks", /if \(p && p\.libraryRef === ref\) count\+\+/.test(etxt));

  // 4. editor.js wiring: the page Inspector's Library section (mirrors renderLibraryInstanceBody).
  var piStart = etxt.indexOf("function renderPageInspector(pi)");
  var piBody = etxt.slice(piStart, piStart + 9200);
  ok("page Inspector reconciles on open (page-level reconcile fn, not the block-level one)", /var prec = reconcilePageOverrides\(pdef\.template\.blocks, page\.overrides \|\| \{\}\)/.test(piBody));
  ok("lists override fields via the canonical fieldRow control", /pfields\.forEach\(function \(f\) \{[\s\S]{0,200}fieldRow\(/.test(piBody));
  ok("offers Detach when linked, Save-to-library when not", /pDetachB\.disabled = !pdef/.test(piBody) && /pSaveB\.addEventListener\("click", function \(\) \{ savePageAsLibraryMaster\(pi\); \}\)/.test(piBody));

  // 5. Library panel lists pages separately, typed/labelled per the acceptance criteria.
  var lStart = etxt.indexOf("function buildLibraryBody(c)");
  var lBody = etxt.slice(lStart, lStart + 12000);
  ok("block-master list excludes page-kind entries", /var keys = Object\.keys\(lib\)\.filter\(function \(k\) \{ return lib\[k\]\.kind !== "page"; \}\)/.test(lBody));
  ok("a separate 'Pages' panelSection lists page-kind masters", /var pageSecBody = panelSection\(c, "Pages"\)/.test(lBody));
  ok("page rows offer Insert page (not Copy to course)", /"prop-btn prop-btn--accent", "Insert page"/.test(lBody));

  // 6. editor.css: the page-scope opacity guard mirrors #20's block-scope one, and never
  // leaks into course.css (editor-only chrome, same invariant as #20).
  ok("pointer-events guard at page scope", /\[data-library-page-instance\] \.canvas-block \{ pointer-events: none; \}/.test(css));
  ok("course.css does not reference the page-instance marker", src("src/course.css").indexOf("data-library-page-instance") === -1);
})();

